package deploy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"text/tabwriter"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/argocd"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// now is the clock, replaced in tests so a deployment can be dated. Mirrors
// internal/release/create.go.
var now = time.Now

// noValue is what an empty cell renders as, matching the diff report.
const noValue = "—"

// Status reports what every environment runs, side by side.
//
// This is the confirmation at the end of the release process. Promotion copies
// digests rather than rebuilding, so the same digest in every row is what makes
// "production runs the bits staging tested" a fact rather than a hope — and
// until now that was only checkable by opening two kustomization.yaml files and
// asking ArgoCD about each application separately.
//
// It writes nothing: no git, no ArgoCD mutation, and kubectl is never invoked.
func Status(ctx context.Context, opts StatusOptions) error {
	opts.applyDefaults()
	out := opts.output()

	// No kustomize: this renders nothing, and demanding a binary it never runs
	// would be a prerequisite for no reason.
	s, err := openSession(ctx, opts.session(), "git")
	if err != nil {
		return err
	}
	defer s.Close()
	repo, deployCfg := s.repo, s.deployCfg

	coord, comp, err := s.locateComponent(opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}

	environments := statusEnvironments(deployCfg, comp)
	rows := make([]EnvironmentStatus, 0, len(environments))
	for _, env := range environments {
		row := readOverlayState(ctx, repo, coord, comp, env)
		if cfg, err := deployCfg.Environment(env); err == nil {
			row.SyncPolicy = cfg.Sync
		}
		rows = append(rows, row)
	}

	observeArgo(ctx, repo, deployCfg, s, opts, rows)

	return reportStatus(out, coord, comp, rows, promotionEdges(deployCfg, environments))
}

// promotionEdges is the promotion graph restricted to the reported
// environments. It rides on the result because deploy.yaml lives in the GitOps
// repository, which a consumer without a session cannot read. Nil when the
// component's environments declare no edges.
func promotionEdges(deployCfg *gitops.DeployConfig, environments []string) map[string][]string {
	var edges map[string][]string
	for _, env := range environments {
		cfg, err := deployCfg.Environment(env)
		if err != nil || len(cfg.PromotesFrom) == 0 {
			continue
		}
		if edges == nil {
			edges = map[string][]string{}
		}
		edges[env] = cfg.PromotesFrom
	}
	return edges
}

// statusEnvironments orders the environments to report.
//
// Promotion order rather than alphabetical: the table's whole claim is about a
// pipeline, and dev, prod, staging tells the wrong story about one. Only the
// environments the component declares are reported — a component need not be
// onboarded everywhere the repository deploys.
//
// An environment the component declares but deploy.yaml does not define is
// appended rather than dropped. It cannot be deployed to, which is exactly the
// sort of thing an operator should see rather than have hidden.
func statusEnvironments(deployCfg *gitops.DeployConfig, comp *gitops.ComponentConfig) []string {
	declared := make(map[string]bool, len(comp.Environments))
	for _, env := range comp.Environments {
		declared[env] = true
	}

	out := make([]string, 0, len(comp.Environments))
	for _, env := range deployCfg.PromotionOrder() {
		if declared[env] {
			out = append(out, env)
			delete(declared, env)
		}
	}
	for _, env := range comp.Environments {
		if declared[env] {
			out = append(out, env)
			delete(declared, env)
		}
	}
	return out
}

// readOverlayState is readSnapshot without the refusals.
//
// readSnapshot rejects an overlay that pins a tag or nothing, because promoting
// out of one would be dishonest about what it copied. Status has the opposite
// duty: an unpinned dev is a fact worth showing next to a correctly pinned prod,
// not a reason to refuse to describe either. Nothing here fails — an
// unreadable environment comes back with Onboarded false and a Reason.
func readOverlayState(ctx context.Context, repo *gitops.Repository, coord gitops.Coordinate, comp *gitops.ComponentConfig, env string) EnvironmentStatus {
	row := EnvironmentStatus{
		Environment: env,
		AppName:     coord.AppName(env),
		OverlayPath: coord.OverlayRelPath(env),
	}

	dir, err := gitops.ResolveOverlay(repo.Root, coord, comp, env)
	if err != nil {
		// The error already explains itself — a missing overlay, or an
		// environment component.yaml does not declare. Its first line is the
		// note; the rest is guidance a table has no room for.
		row.Reason = firstLine(err.Error())
		return row
	}
	k, _, err := kustomize.ReadKustomization(dir)
	if err != nil {
		row.Reason = firstLine(err.Error())
		return row
	}

	row.Onboarded = true
	row.Release = k.CommonAnnotations[kustomize.AnnotationRelease]
	row.SourceCommit = k.CommonAnnotations[kustomize.AnnotationSourceCommit]

	// Every declared image, in declared order, whether or not the overlay pins
	// it: an image missing from the overlay is the most interesting row there
	// is, and omitting it would hide it.
	for _, img := range comp.Images {
		pin := ResultPin{Image: img.Name}
		if entry, found := k.FindImage(img.Name); found {
			pin.Digest, pin.Tag = entry.Digest, entry.NewTag
		}
		row.Pins = append(row.Pins, pin)
	}

	revision, at, found, err := repo.Git.LastCommitAt(ctx, "HEAD", coord.OverlayRelPath(env))
	if err == nil && found {
		row.Revision = revision
		row.DeployedAt = &at
	}
	return row
}

// observeArgo fills in the sync and health of each row, in place.
//
// Unreachable ArgoCD is a warning rather than a failure, unlike sync and diff
// where there is no command at all without the API call. Everything to the left
// of those two columns was read from git and is still true; refusing to print
// the digests because the cluster is unreachable would withhold most of the
// answer over part of it.
func observeArgo(ctx context.Context, repo *gitops.Repository, deployCfg *gitops.DeployConfig, s *session, opts StatusOptions, rows []EnvironmentStatus) {
	client, creds, err := connect(deployCfg, opts.ArgocdServer, s.argocdServer, opts.UserAgent)
	if err != nil {
		fmt.Fprintf(opts.Stderr, "warning: not reading sync or health from ArgoCD: %v\n", err)
		return
	}
	fmt.Fprintf(opts.Stderr, "reading %d application(s) from %s\n", len(rows), creds.Server)

	for i := range rows {
		app, err := client.Get(ctx, rows[i].AppName)
		if err != nil {
			if errors.Is(err, argocd.ErrUnreachable) {
				// The server is down or the token is stale. Every remaining
				// request would fail the same way, so stop asking.
				fmt.Fprintf(opts.Stderr, "warning: %v\n", err)
				return
			}
			// A single unknown application: the component is onboarded in git
			// but its Application does not exist, or not under this namespace.
			// The other rows are unaffected.
			fmt.Fprintf(opts.Stderr, "warning: %s: %v\n", rows[i].AppName, err)
			continue
		}

		rows[i].SyncStatus = app.Status.Sync.Status
		rows[i].HealthStatus = app.Status.Health.Status
		rows[i].SyncedRevision = app.Status.Sync.Revision
		rows[i].LiveImages = app.Status.Summary.Images

		// Pending is a git question, not an ArgoCD one: has the commit that
		// last changed this overlay reached the cluster? A descendant counts,
		// which is why this is revisionContains rather than an equality test.
		if rows[i].Revision != "" {
			applied, err := revisionContains(repo)(ctx, rows[i].Revision, app.Status.Sync.Revision)
			if err == nil {
				rows[i].Pending = !applied
			}
		}
	}
}

// pinSignature is an environment's digests, in declared image order.
//
// Empty when the overlay does not pin a digest for every image — there is then
// no set of bits to compare, which is a different thing from disagreeing about
// one.
func pinSignature(row EnvironmentStatus) string {
	if !row.Onboarded || len(row.Pins) == 0 {
		return ""
	}
	digests := make([]string, 0, len(row.Pins))
	for _, pin := range row.Pins {
		if pin.Digest == "" {
			return ""
		}
		digests = append(digests, pin.Digest)
	}
	return strings.Join(digests, " ")
}

// consistent reports whether every onboarded environment pins the identical
// digest for every image.
//
// An environment that pins no digest makes the answer false rather than being
// skipped: the claim is "everything agrees", and an environment nobody can
// compare has not been shown to agree with anything.
func consistent(rows []EnvironmentStatus) bool {
	signature, seen := "", false
	for _, row := range rows {
		if !row.Onboarded {
			continue
		}
		s := pinSignature(row)
		if s == "" {
			return false
		}
		if seen && s != signature {
			return false
		}
		signature, seen = s, true
	}
	return seen
}

// reportStatus writes the table, then the answer to the question that prompted
// it. Exit is always 0: this reports, it does not gate.
func reportStatus(out output, coord gitops.Coordinate, comp *gitops.ComponentConfig, rows []EnvironmentStatus, promotesFrom map[string][]string) error {
	// Built for both formats, and the table below renders from it rather than
	// recomputing: two presenters deriving the same claim independently is how
	// they come to disagree about it.
	res := StatusResult{
		Component:    coord.Component,
		Domain:       coord.Domain,
		System:       coord.System,
		Kind:         componentKind(comp),
		Environments: rows,
		Consistent:   consistent(rows),
		Summary:      summarise(rows),
		Notes:        notes(coord, comp, rows),
		PromotesFrom: promotesFrom,
	}

	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(res); err != nil {
			return fmt.Errorf("write JSON result: %w", err)
		}
		return nil
	}

	tw := tabwriter.NewWriter(out.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "COMPONENT\tENV\tRELEASE\tDIGEST\tAGE\tSYNC\tHEALTH")
	for _, row := range rows {
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			coord.Component, row.Environment, releaseCell(row), digestCell(row),
			ageCell(row), orNone(row.SyncStatus), orNone(row.HealthStatus))
	}
	if err := tw.Flush(); err != nil {
		return err
	}

	fmt.Fprintf(out.Stdout, "\n%s\n", res.Summary)
	for _, note := range res.Notes {
		fmt.Fprintf(out.Stdout, "%s\n", note)
	}
	if note := tableNote(coord, comp); note != "" {
		fmt.Fprintf(out.Stdout, "%s\n", note)
	}
	return nil
}

// releaseCell is the version the environment runs.
//
// An environment deployed from a commit has no release annotation but still has
// something true to say, so the source commit stands in. The @ prefix is what
// keeps it from being misread as a version.
func releaseCell(row EnvironmentStatus) string {
	switch {
	case row.Release != "":
		return row.Release
	case row.SourceCommit != "":
		return "@" + git.ShortSHA(row.SourceCommit)
	default:
		return noValue
	}
}

// digestCell is what the overlay pins for the first declared image.
//
// The first only — one row per environment is what makes the table scannable,
// and the multi-image case is covered by a note plus the full list in JSON.
// shortDigest is reused rather than abbreviated further so this is
// character-for-character the digest deploy and promote print.
func digestCell(row EnvironmentStatus) string {
	if !row.Onboarded || len(row.Pins) == 0 {
		return noValue
	}
	switch pin := row.Pins[0]; {
	case pin.Digest != "":
		return shortDigest(pin.Digest)
	case pin.Tag != "":
		return ":" + pin.Tag
	default:
		return noValue
	}
}

func ageCell(row EnvironmentStatus) string {
	if row.DeployedAt == nil {
		return noValue
	}
	return humanAge(now().Sub(*row.DeployedAt))
}

func orNone(s string) string {
	if s == "" {
		return noValue
	}
	return s
}

// humanAge renders how long ago a deployment landed, at one unit.
//
// Truncating rather than rounding: 119 minutes is "1h", never "2h". A
// deployment reading as older than it is would be read as a change someone else
// already reviewed.
func humanAge(d time.Duration) string {
	switch {
	case d < time.Minute:
		return "<1m"
	case d < time.Hour:
		return fmt.Sprintf("%dm", int(d.Minutes()))
	case d < 48*time.Hour:
		return fmt.Sprintf("%dh", int(d.Hours()))
	default:
		return fmt.Sprintf("%dd", int(d.Hours())/24)
	}
}

// summarise answers the question the command was asked.
//
// Environments that pin no digest are held apart from those that do rather than
// grouped with each other: "these two run different bits" and "there is nothing
// to compare here" are different findings, and merging them would report a
// disagreement between two environments that were never compared.
func summarise(rows []EnvironmentStatus) string {
	var comparable, unpinned []EnvironmentStatus
	for _, row := range rows {
		switch {
		case !row.Onboarded:
		case pinSignature(row) == "":
			unpinned = append(unpinned, row)
		default:
			comparable = append(comparable, row)
		}
	}

	if len(comparable)+len(unpinned) == 0 {
		return "no environment has a readable overlay, so there is nothing to compare"
	}

	// Group by what each environment runs, keeping first appearance in
	// promotion order so the upstream environment is named first.
	var signatures []string
	byDigest := map[string][]string{}
	for _, row := range comparable {
		s := pinSignature(row)
		if _, seen := byDigest[s]; !seen {
			signatures = append(signatures, s)
		}
		byDigest[s] = append(byDigest[s], row.Environment)
	}

	if len(signatures) == 0 {
		return fmt.Sprintf("%s %s no digest, so there is nothing to compare",
			englishList(environmentNames(unpinned)), conjugate(len(unpinned), "pin"))
	}
	if len(signatures) == 1 && len(unpinned) == 0 {
		if len(comparable) == 1 {
			return fmt.Sprintf("only %s is onboarded, so there is nothing to compare it with", comparable[0].Environment)
		}
		return fmt.Sprintf("all %d environments run %s (same digest, promoted rather than rebuilt)",
			len(comparable), describeSignatureString(signatures[0]))
	}

	clauses := make([]string, 0, len(signatures)+1)
	for _, s := range signatures {
		envs := byDigest[s]
		clauses = append(clauses, fmt.Sprintf("%s %s %s", englishList(envs), conjugate(len(envs), "run"), describeSignatureString(s)))
	}
	if len(unpinned) > 0 {
		clauses = append(clauses, fmt.Sprintf("%s %s no digest at all",
			englishList(environmentNames(unpinned)), conjugate(len(unpinned), "pin")))
	}
	return "environments disagree: " + strings.Join(clauses, "; ")
}

func environmentNames(rows []EnvironmentStatus) []string {
	out := make([]string, 0, len(rows))
	for _, row := range rows {
		out = append(out, row.Environment)
	}
	return out
}

// conjugate agrees the verb with the number of environments named: one
// environment "runs", several "run".
func conjugate(n int, base string) string {
	if n == 1 {
		return base + "s"
	}
	return base
}

func describeSignatureString(signature string) string {
	digests := strings.Fields(signature)
	if len(digests) == 1 {
		return shortDigest(digests[0])
	}
	short := make([]string, 0, len(digests))
	for _, d := range digests {
		short = append(short, shortDigest(d))
	}
	return strings.Join(short, " + ")
}

// notes are the qualifications under the summary: what could not be read, what
// pins a tag, and what is waiting.
//
// Every note here is about the deployment, so it is equally true in both output
// formats and travels in StatusResult. The one qualification that is about the
// table itself lives in tableNote.
func notes(coord gitops.Coordinate, comp *gitops.ComponentConfig, rows []EnvironmentStatus) []string {
	var out []string

	// A shared component declares no images, so every DIGEST cell is empty. Said
	// plainly and first, because an empty column otherwise reads as "never
	// deployed" — the one conclusion a reader must not draw here. A KIND column
	// would carry this too, at the cost of a mostly-"service" column in every
	// other component's table.
	if comp.IsShared() {
		out = append(out, fmt.Sprintf("%s is kind %q: it holds system-level manifests and no image, so DIGEST is empty by design",
			coord.Component, gitops.KindShared))
	}

	for _, row := range rows {
		switch {
		case !row.Onboarded:
			out = append(out, fmt.Sprintf("%s: %s", row.Environment, row.Reason))
		default:
			for _, pin := range row.Pins {
				if pin.Digest != "" {
					continue
				}
				if pin.Tag != "" {
					out = append(out, fmt.Sprintf("%s pins %s to the tag %q rather than a digest — it can drift without a deployment",
						row.Environment, pin.Image, pin.Tag))
					continue
				}
				out = append(out, fmt.Sprintf("%s pins nothing for %s, so it has never been deployed there", row.Environment, pin.Image))
			}
		}
	}

	for _, row := range rows {
		if !row.Pending {
			continue
		}
		waiting := "waiting to be applied"
		if row.SyncPolicy == gitops.SyncManual {
			waiting = "waiting on its manual sync gate"
		}
		out = append(out, fmt.Sprintf("%s has a committed change ArgoCD has not applied, %s:\n  intropy deploy diff %s --env %s",
			row.Environment, waiting, coord.Component, row.Environment))
	}

	return out
}

// tableNote is the qualification the table needs and the result does not.
//
// The consistency claim is computed over every image, so it is never narrower
// than the data behind it — but DIGEST has room for one, and a reader should know
// that before drawing a conclusion from the column. A consumer reading the result
// already has every pin in Environments[].Pins, so telling it to ask for what it
// is holding would be false rather than merely redundant.
func tableNote(coord gitops.Coordinate, comp *gitops.ComponentConfig) string {
	if len(comp.Images) <= 1 {
		return ""
	}
	return fmt.Sprintf("%s declares %d images; DIGEST shows %s. Use --output json for all of them",
		coord.Component, len(comp.Images), comp.Images[0].Name)
}

// englishList renders names as "a", "a and b", or "a, b and c".
func englishList(names []string) string {
	switch len(names) {
	case 0:
		return ""
	case 1:
		return names[0]
	default:
		return strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
	}
}

// firstLine trims a multi-line error down to something a note can carry. The
// errors these come from append guidance on later lines, which is useful at a
// prompt and noise under a table row.
func firstLine(s string) string {
	line, _, _ := strings.Cut(s, "\n")
	return line
}

package deploy

import "time"

// Result is the machine-readable outcome. Field names are stable and
// additive-only.
type Result struct {
	Component    string      `json:"component"`
	Domain       string      `json:"domain"`
	System       string      `json:"system"`
	Environment  string      `json:"environment"`
	SourceCommit string      `json:"sourceCommit"`
	AppName      string      `json:"appName"`
	OverlayPath  string      `json:"overlayPath"`
	Pins         []ResultPin `json:"pins"`
	Changed      bool        `json:"changed"`

	// Applied reports whether the change was committed and pushed.
	Applied bool `json:"applied"`

	// Revision is the sha that landed on the GitOps branch. Empty unless
	// Applied. It is the post-rebase sha, which is what ArgoCD reports back.
	Revision string `json:"revision,omitempty"`

	// Release is the version deployed. Empty when the digests were resolved
	// from the source repository's HEAD.
	Release string `json:"release,omitempty"`

	// PromotedFrom is the environment the digests were copied from. Present only
	// for a promotion, which resolves nothing and so has no other record of
	// where its digests came from.
	PromotedFrom string `json:"promotedFrom,omitempty"`

	// Upstreams reports what the environments this one promotes from currently
	// have pinned, so a consumer can see whether these are the bits that were
	// tested upstream. Informational: a mismatch never fails the deploy.
	Upstreams []Upstream `json:"upstreams,omitempty"`

	SyncPolicy string `json:"syncPolicy"`

	// SyncStatus, HealthStatus and SyncedRevision are what ArgoCD reported once
	// it converged. Empty when the wait was skipped, the environment syncs
	// manually, or ArgoCD could not be reached — none of which means the
	// deployment failed.
	SyncStatus     string `json:"syncStatus,omitempty"`
	HealthStatus   string `json:"healthStatus,omitempty"`
	SyncedRevision string `json:"syncedRevision,omitempty"`
}

// SyncResult is the machine-readable outcome of a sync. Its own type rather than
// a Result: a sync pins nothing and plans nothing, so most of Result's fields
// would be permanently empty.
type SyncResult struct {
	Component   string `json:"component"`
	Domain      string `json:"domain"`
	System      string `json:"system"`
	Environment string `json:"environment"`
	AppName     string `json:"appName"`
	OverlayPath string `json:"overlayPath"`

	// Revision is the commit that was synced: the one that last changed the
	// overlay, which is what was reviewed.
	Revision string `json:"revision"`

	// Requested reports whether a sync was actually asked for. False means
	// ArgoCD already held that revision and was left alone.
	Requested bool `json:"requested"`

	SyncPolicy string `json:"syncPolicy"`

	// SyncStatus, HealthStatus and SyncedRevision are what ArgoCD reported once
	// it converged. Empty when --no-wait was given or ArgoCD became unreachable
	// after the sync was accepted.
	SyncStatus     string `json:"syncStatus,omitempty"`
	HealthStatus   string `json:"healthStatus,omitempty"`
	SyncedRevision string `json:"syncedRevision,omitempty"`
}

// DiffResult is the machine-readable outcome of a diff. Its own type for the same
// reason SyncResult is: nothing here is pinned, planned or applied.
type DiffResult struct {
	Component   string `json:"component"`
	Domain      string `json:"domain"`
	System      string `json:"system"`
	Environment string `json:"environment"`
	AppName     string `json:"appName"`
	OverlayPath string `json:"overlayPath"`

	// Pending is the full sha a sync would apply — full rather than abbreviated
	// because it is meant to be handed straight to `sync --revision`, whose
	// comparison is a prefix match that an abbreviation only weakens.
	Pending string `json:"pending"`

	// Synced is the revision ArgoCD reports it has applied, and the baseline the
	// diff is against. Empty when the application has never been synced, in which
	// case every resource below is new.
	Synced string `json:"synced,omitempty"`

	// Applied reports that ArgoCD already holds the pending revision, or a
	// descendant of it.
	Applied bool `json:"applied"`

	// Changed reports whether the two renders differ at all.
	Changed bool `json:"changed"`

	// Diff is the unified diff of the two renders, never coloured in this form.
	Diff string `json:"diff,omitempty"`

	// RemovedResources are the resources the baseline renders and the pending
	// revision does not. They will not leave the cluster: a sync from here does
	// not prune.
	RemovedResources []string `json:"removedResources,omitempty"`

	// Subject, Release, PromotedFrom, SourceCommit and DeployedBy are what the
	// pending commit says about itself, read from its trailers. An approver's
	// other question is who asked for this, and from what.
	Subject      string `json:"subject,omitempty"`
	Release      string `json:"release,omitempty"`
	PromotedFrom string `json:"promotedFrom,omitempty"`
	SourceCommit string `json:"sourceCommit,omitempty"`
	DeployedBy   string `json:"deployedBy,omitempty"`

	SyncPolicy   string `json:"syncPolicy"`
	SyncStatus   string `json:"syncStatus,omitempty"`
	HealthStatus string `json:"healthStatus,omitempty"`
}

// StatusResult is the machine-readable outcome of a status. Its own type for
// the same reason SyncResult is: it plans nothing, applies nothing, and is the
// only result here that describes more than one environment.
// InitResult is the machine-readable summary of a deploy init run.
//
// Placeholders is the point of the document: complete manifests are explicitly
// not the goal, so what a consumer wants to know is exactly which values a human
// still has to supply and where.
type InitResult struct {
	System string `json:"system"`
	Domain string `json:"domain"`

	// Host is the component directory holding the system's shared manifests.
	Host string `json:"host"`

	// Template is the resolved template library reference, so a reviewer can tell
	// which release produced the tree.
	Template string `json:"template"`

	Components []string `json:"components"`

	// Files is every staged path and what was done with it, including the ones
	// left alone.
	Files []FileAction `json:"files"`

	// Applied is false for --plan and for a run that found nothing to write.
	Applied  bool   `json:"applied"`
	Branch   string `json:"branch,omitempty"`
	Revision string `json:"revision,omitempty"`

	Placeholders []Placeholder `json:"placeholders"`
}

type StatusResult struct {
	Component string `json:"component"`
	Domain    string `json:"domain"`
	System    string `json:"system"`

	// Kind is the component's declared kind, always populated even when
	// component.yaml leaves it implicit. A consumer reading empty digests needs
	// to tell "shared, so there is nothing to pin" from "never deployed".
	Kind string `json:"kind"`

	// Environments are in promotion order, so the last one is the furthest
	// downstream — usually production.
	Environments []EnvironmentStatus `json:"environments"`

	// Consistent reports that every onboarded environment pins the identical
	// digest for every image the component declares. This is the question the
	// command exists to answer: promotion copies digests rather than rebuilding,
	// so agreement here is what makes "prod runs the bits staging tested" true.
	//
	// False when any environment disagrees, pins a tag instead of a digest, or
	// could not be read — in none of those cases has agreement been shown.
	Consistent bool `json:"consistent"`

	// Summary is the sentence the plain output prints beneath its table: what
	// the environments collectively run, or why they cannot be compared.
	//
	// It travels in the result because Consistent is a bool and the interesting
	// cases are not: "these two run different bits" and "there is nothing to
	// compare here" are both false and mean very different things. A second
	// presenter deriving its own sentence from Environments would eventually
	// draw a different conclusion from the same rows than this command does.
	Summary string `json:"summary"`

	// Notes are the qualifications under that sentence: an environment that
	// could not be read, one that pins a tag rather than a digest, one waiting
	// on a sync gate. Empty when there is nothing to qualify.
	//
	// The plain output adds one more note that is about its own table rather
	// than about the deployment, and so is deliberately absent here.
	Notes []string `json:"notes,omitempty"`

	// PromotesFrom is the promotion graph restricted to this component's
	// environments: for each environment, the environments a promotion into it
	// may draw from. It rides on the result because deploy.yaml lives in the
	// GitOps repository, which a consumer without a session cannot read.
	// Absent when the component's environments declare no promotion edges.
	PromotesFrom map[string][]string `json:"promotesFrom,omitempty"`
}

// EnvironmentStatus is one environment's row.
type EnvironmentStatus struct {
	Environment string `json:"environment"`
	AppName     string `json:"appName"`
	OverlayPath string `json:"overlayPath"`

	// Onboarded reports that the component has a readable overlay here. False
	// leaves everything below it empty, and Reason says why.
	Onboarded bool   `json:"onboarded"`
	Reason    string `json:"reason,omitempty"`

	// Release and SourceCommit are the deploy.internal/release and
	// deploy.internal/source-commit annotations. Release is empty when the
	// environment was deployed from a commit rather than a release.
	Release      string `json:"release,omitempty"`
	SourceCommit string `json:"sourceCommit,omitempty"`

	// Pins is every image the component declares, in that order — not just the
	// one the table has room for. Digest is empty when the overlay pins a tag
	// or nothing, in which case Tag says which.
	Pins []ResultPin `json:"pins,omitempty"`

	// Revision is the GitOps commit that last changed this overlay, and
	// DeployedAt when it landed. Both empty when the path has no history.
	Revision   string     `json:"revision,omitempty"`
	DeployedAt *time.Time `json:"deployedAt,omitempty"`

	SyncPolicy string `json:"syncPolicy"`

	// SyncStatus, HealthStatus and SyncedRevision are what ArgoCD reports.
	// Empty when it could not be reached or does not know this application —
	// neither of which says anything about what the overlay pins.
	SyncStatus     string `json:"syncStatus,omitempty"`
	HealthStatus   string `json:"healthStatus,omitempty"`
	SyncedRevision string `json:"syncedRevision,omitempty"`

	// LiveImages is what ArgoCD observed running in the cluster, as opposed
	// to what the overlay pins. Absent under the same rule as SyncStatus:
	// its absence says nothing about the overlay or the cluster.
	LiveImages []string `json:"liveImages,omitempty"`

	// Pending reports a committed overlay change ArgoCD has not applied. For a
	// manual-sync environment that is the normal resting state of an unspent
	// gate, not a fault.
	Pending bool `json:"pending"`
}

// ResultPin is one image's before and after state.
type ResultPin struct {
	Image    string `json:"image"`
	Previous string `json:"previous,omitempty"`
	Digest   string `json:"digest"`

	// Tag is the tag the digest was resolved from. Empty when the digest came
	// from a release manifest, which records digests rather than tags.
	Tag string `json:"tag,omitempty"`
}

package deploy

import (
	"context"
	"fmt"
	"io"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// session is the state every command in this package starts from: a refreshed
// GitOps checkout and the repository-level policy in it.
type session struct {
	repo      *gitops.Repository
	deployCfg *gitops.DeployConfig

	// argocdServer is argocdServer from the user's configuration file, the last
	// resort when neither the flag nor deploy.yaml names one.
	argocdServer string
}

// sessionOptions is the subset of a command's options openSession needs.
type sessionOptions struct {
	GitopsRepo   string
	ArgocdServer string
	CacheRoot    string
	Runner       command.Runner
	Stderr       io.Writer
}

// openSession resolves the GitOps repository, refreshes the cached checkout and
// loads deploy.yaml.
//
// binaries are required up front, before any network or cache work: discovering
// a missing kustomize after cloning wastes the user's time. Which ones is the
// caller's business — sync renders nothing, so demanding kustomize of it would
// be a prerequisite it never uses.
//
// The caller owns the returned repository and must Close it.
func openSession(ctx context.Context, opts sessionOptions, binaries ...string) (*session, error) {
	if err := command.RequireBinaries(binaries...); err != nil {
		return nil, err
	}

	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo, ArgocdServer: opts.ArgocdServer})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return nil, err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot, Stderr: opts.Stderr})
	if err != nil {
		return nil, err
	}
	// Open has already refused a push address that is a different repository, so
	// anything left is the same repository under another name — an insteadOf
	// rewrite. Worth showing: the address a deployment leaves for is not something
	// to discover afterwards.
	if repo.PushURL != "" && repo.PushURL != repoURL {
		fmt.Fprintf(opts.Stderr, "note: git pushes %s as %s\n", repoURL, repo.PushURL)
	}

	deployCfg, err := gitops.LoadDeployConfig(repo.Root)
	if err != nil {
		repo.Close()
		return nil, err
	}

	return &session{repo: repo, deployCfg: deployCfg, argocdServer: resolved.ArgocdServer}, nil
}

func (s *session) Close() { s.repo.Close() }

// locateComponent finds the component in the GitOps tree and reads its
// component.yaml. domain and system disambiguate a name that occurs more than
// once.
func (s *session) locateComponent(component, domain, system string) (gitops.Coordinate, *gitops.ComponentConfig, error) {
	coord, err := gitops.FindComponent(s.repo.Root, component, domain, system)
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	comp, err := gitops.LoadComponentConfig(componentDir(s.repo.Root, coord))
	if err != nil {
		return gitops.Coordinate{}, nil, err
	}
	return coord, comp, nil
}

// componentKind is the component's kind with the default made explicit, so a
// reported value never depends on whether component.yaml spelled it out.
func componentKind(comp *gitops.ComponentConfig) string {
	if comp.Kind == "" {
		return gitops.KindService
	}
	return comp.Kind
}

// requirePinnable rejects a component that has no image to pin.
//
// deploy and promote exist to move image digests, so a shared component is a
// category error for them rather than a run that happens to change nothing —
// without this the plan would come out empty and read as "already up to date".
// status, diff and sync all work on a shared component and must not call this.
func requirePinnable(coord gitops.Coordinate, comp *gitops.ComponentConfig) error {
	if !comp.IsShared() {
		return nil
	}
	return fmt.Errorf("%s is kind %q; it declares no images, so there is nothing to pin — edit its manifests directly", coord, gitops.KindShared)
}

package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// deployProvider reports what one integration has deployed, where.
//
// Like topologyProvider it never fails: a component that cannot be described
// comes back with Error set rather than an error return, because "we could not
// find out" and "it is not deployed" must not render the same. Which of the two
// it was is the command's business to say, not this package's to guess.
type deployProvider func(ctx context.Context, s integrationSummary) deployState

// deployState is one integration's deployment state, or the reason it has none.
type deployState struct {
	// Status is deploy status's own result, passed through unchanged so that the
	// dashboard and the command line cannot come to different conclusions about
	// the same overlays.
	Status *deploy.StatusResult `json:"status,omitempty"`

	// Error is the command's own message, verbatim — an unconfigured GitOps
	// repository, a component name that matches several, a checkout another
	// deploy is holding. Served rather than restated: those messages already
	// name every way to resolve them, and a paraphrase here would be a second
	// thing to keep true. The one exception is a component the GitOps tree
	// does not know at all, which describeError renders as "not deployed yet".
	//
	// None of them is a statement about the integration. Only the environments
	// inside Status say whether something is deployed.
	Error string `json:"error,omitempty"`

	// Diagnostics is what the command wrote to stderr, one entry per line:
	// which repository it refreshed, and any environment ArgoCD could not be
	// read for. Provenance for what Status shows, not a failure.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// ReadAt is when the command ran, so a reader can tell how current this is.
	ReadAt time.Time `json:"readAt"`
}

// statusCommandProvider is the default provider: it runs the deploy status
// command with a JSON writer and decodes what it prints.
//
// Calling the command rather than reading the GitOps tree here is deliberate.
// Status already owns every refusal that matters — an unset gitopsRepo, an
// ambiguous component, an overlay that pins a tag, an environment nobody has
// onboarded, an unreachable ArgoCD — and each of those is a case where the
// honest answer is subtle and already written down. A second implementation
// would have to get all of them right again.
//
// Domain and System travel with the component name for the same reason
// deploy status takes them as flags: component names are not unique across a
// GitOps tree, and the command refuses an ambiguous one rather than picking.
func statusCommandProvider(version string) deployProvider {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context, s integrationSummary) deployState {
		var out, logs bytes.Buffer
		err := deploy.Status(ctx, deploy.StatusOptions{
			Component:    s.Name,
			Domain:       s.Domain,
			System:       s.System,
			OutputFormat: deploy.OutputJSON,
			UserAgent:    userAgent,
			Stdout:       &out,
			Stderr:       &logs,
		})

		state := deployState{Diagnostics: diagnosticLines(logs.String()), ReadAt: time.Now()}
		if err != nil {
			state.Error = describeError(s, err)
			return state
		}

		var res deploy.StatusResult
		if err := json.Unmarshal(out.Bytes(), &res); err != nil {
			// The command succeeded but printed something this cannot read —
			// a version skew rather than anything about the deployment.
			state.Error = fmt.Sprintf("read deploy status output: %v", err)
			return state
		}
		state.Status = &res
		return state
	}
}

// describeError serves the command's message verbatim, with one exception:
// every component-not-found reads in the dashboard as "not deployed yet".
// The command's variants — listing what the repository defines, or pointing
// at the coordinate a mistyped --domain/--system missed — are actionable at
// a prompt. Here the domain and system come from the workspace folders, so
// the correction is noise and the fact is the same: nothing is deployed
// under that name.
func describeError(s integrationSummary, err error) string {
	if errors.Is(err, gitops.ErrComponentNotFound) {
		return fmt.Sprintf("%s is not deployed yet", s.Name)
	}
	return err.Error()
}

// diagnosticLines splits captured stderr into entries, dropping blanks. Nil for
// no output, so the field is omitted rather than served as an empty array.
func diagnosticLines(stderr string) []string {
	var out []string
	for line := range strings.SplitSeq(stderr, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, line)
		}
	}
	return out
}

package dashboard

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
// the detail endpoint returns, so a huge file cannot bloat a response.
const maxDocBytes = 128 * 1024

// providers are the request-independent sources the API reads beyond the
// workspace's own files: what a system host declares about its topology, and
// what the GitOps repository says is deployed. Both run a command, so both are
// injected as function values that tests replace.
type providers struct {
	topology topologyProvider
	deploy   deployProvider
}

// deployStateTimeout bounds one deploy status run.
//
// It exists for the checkout lock rather than for the browser: the command holds
// an exclusive lock on the shared GitOps checkout for its whole duration, and an
// ArgoCD server that accepts connections but never answers would otherwise keep
// that lock — blocking the user's own intropy deploy indefinitely. A minute is
// generous for a fetch plus a handful of ArgoCD calls and short enough that a
// hung one lets go.
const deployStateTimeout = time.Minute

// apiServer holds the request-independent state for the JSON API.
type apiServer struct {
	root    string
	version string
	topo    topologyProvider
	dep     deployProvider

	// topoMu guards the cached provider result. Fetching runs the hosts'
	// graph verbs (a dotnet build on first run), so the result is computed
	// once — on the first /api/topology request — and reused until an
	// explicit refresh.
	topoMu      sync.Mutex
	topoLoaded  bool
	topoWarming bool
	topoEntries []topology.Entry
	topoErrs    []string

	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState
}

// topologyReport is the /api/topology payload: every declared topology plus
// the per-host failures the UI renders. Topologies is always an array (never
// null) even when empty.
type topologyReport struct {
	Topologies []topologyEntry `json:"topologies"`
	Errors     []string        `json:"errors,omitempty"`
}

// topologyEntry is one system's declared topology plus the authored
// enrichment read from its directory: message descriptions keyed by connector
// name. The docs ride beside the Topology rather than inside it — the
// topology stays exactly what the host declared.
type topologyEntry struct {
	topology.Entry
	MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
}

// fileDoc is a text document surfaced in an integration's detail view.
type fileDoc struct {
	Name    string `json:"name"`
	Content string `json:"content"`
}

// integrationSummary is a scaffold entry plus the coordinates the sidebar
// tree groups by: Name is the directory that carries the .intropy record.
// System is the name a sibling system-host scaffold declares for the
// directory's parent, falling back to the parent folder's name; Domain is the
// system's parent folder. Absent a host, System is empty when the integration
// sits directly under the workspace root, and Domain is empty when the
// system does.
type integrationSummary struct {
	template.ScaffoldEntry
	Name   string `json:"name"`
	System string `json:"system,omitempty"`
	Domain string `json:"domain,omitempty"`
	// SystemPath is the root-relative directory of the system the integration
	// belongs to ("." when the system is rooted at the workspace itself).
	// Unlike System — a declared name two directories can share — it is a
	// unique grouping key, and it matches the `path` of the topology record
	// the system's host produces. Absent when the integration has no system.
	SystemPath string `json:"systemPath,omitempty"`
}

// integrationDetail is a single integration plus best-effort, on-disk
// enrichment. Every enrichment field is optional and absent when the
// corresponding file or directory does not exist.
type integrationDetail struct {
	integrationSummary
	Agents        *fileDoc        `json:"agents,omitempty"`
	Readme        *fileDoc        `json:"readme,omitempty"`
	Components    []DaprComponent `json:"components,omitempty"`
	PipelineSteps []string        `json:"pipelineSteps,omitempty"`
}

// newHandler wires the API routes and the SPA static handler onto a mux.
func newHandler(root, version string, p providers) (http.Handler, error) {
	api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy}
	static, err := staticHandler()
	if err != nil {
		return nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", api.health)
	mux.HandleFunc("GET /api/integrations", api.listIntegrations)
	mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
	mux.HandleFunc("GET /api/catalog/{path...}", api.catalog)
	mux.HandleFunc("GET /api/flow", api.flow)
	mux.HandleFunc("GET /api/topology", api.topologies)
	mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
	// The verb carries the meaning rather than a /refresh segment: a {path...}
	// wildcard has to be the last thing in the pattern. GET serves what has
	// already been read, POST runs the command again.
	mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
	mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
	mux.Handle("/", static)
	return mux, nil
}

func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status":  "ok",
		"version": s.version,
	})
}

// listIntegrations mirrors `int list -o json` — the same scaffold entries in
// the same order — with the derived name/system fields added on top and each
// Path normalized to a root-relative identifier. The response is always an
// array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, s.summarize(e, systems))
	}
	writeJSON(w, http.StatusOK, summaries)
}

// scan splits the workspace's scaffold entries for the API: the integration
// blocks to catalog, plus the declared systems keyed by their root directory
// (the directory holding a system-host scaffold). Support projects — the host
// and its shared contracts library — are infrastructure the system view
// already represents, not integrations to list.
func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
	entries, _ := template.ListScaffolds(s.root)
	systems = map[string]string{}
	for _, e := range entries {
		if e.Role == template.RoleSystemHost {
			systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
		}
	}
	blocks = entries[:0]
	for _, e := range entries {
		if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
			continue
		}
		blocks = append(blocks, e)
	}
	return blocks, systems
}

// systemName is the name a system-host scaffold declares for its system
// (the template's `name` value, recorded at `sys create`), falling back to
// the host's parent directory name.
func systemName(host template.ScaffoldEntry) string {
	if name, ok := host.Values["name"].(string); ok && name != "" {
		return name
	}
	dir := filepath.Dir(host.Path)
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// summarize derives an entry's tree coordinates from its path and the
// declared systems. A sibling system-host makes membership explicit: its
// declared name wins over the folder-derived one and applies even directly
// under the workspace root (where no folder-derived system exists).
// Otherwise the workspace root itself never counts as a system or domain, so
// an integration scaffolded at the root has neither and one directly under
// the root has a system but no domain. The served Path is made root-relative
// so it is a stable, URL-safe identifier regardless of whether the command
// was given a relative or absolute root (an absolute path would otherwise
// break detail lookups).
func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
	sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
	sum.Path = s.relPath(e.Path)
	path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
	parent := filepath.Dir(path)
	if declared, ok := systems[parent]; ok && path != root {
		sum.System = declared
		sum.SystemPath = s.relPath(parent)
		if grand := filepath.Dir(parent); parent != root && grand != root {
			sum.Domain = filepath.Base(grand)
		}
		return sum
	}
	if path == root || parent == root {
		return sum
	}
	sum.System = filepath.Base(parent)
	sum.SystemPath = s.relPath(parent)
	if grand := filepath.Dir(parent); grand != root {
		sum.Domain = filepath.Base(grand)
	}
	return sum
}

// relPath turns an entry's on-disk path into the root-relative, slash-separated
// identifier used in API responses and URLs. It falls back to the cleaned path
// so a value is always produced even if Rel fails (e.g. differing volumes).
func (s *apiServer) relPath(p string) string {
	if rel, err := filepath.Rel(s.root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

// flow returns every integration enriched with the pipeline steps and Dapr
// components the flow canvas draws, so the whole graph loads in one request.
// It reuses integrationDetail but leaves the document fields (agents/readme)
// nil — the canvas nodes do not render them.
func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	nodes := make([]integrationDetail, 0, len(entries))
	for _, e := range entries {
		dir := e.Path
		nodes = append(nodes, integrationDetail{
			integrationSummary: s.summarize(e, systems),
			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
		})
	}
	writeJSON(w, http.StatusOK, nodes)
}

// topologies returns every system topology declared by a host's graph verb,
// each Path normalized to the same root-relative identifier integration
// paths use, so the flow canvas can match a topology to the integrations
// living beside its host. The provider result is cached after the first
// request (the verb builds the host); POST /api/topology/refresh recomputes.
func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
}

// refreshTopologies recomputes the topology cache by re-running every host's
// graph verb, then returns the fresh report.
func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
}

// topologyReport assembles the /api/topology payload: the cached provider
// result plus the message docs read fresh from disk on every request, so an
// edited doc shows up on a browser refresh without re-running the hosts'
// graph verbs.
func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
	entries, errs := s.cachedTopologies(ctx, force)
	report := topologyReport{
		Topologies: make([]topologyEntry, 0, len(entries)),
		Errors:     append([]string(nil), errs...),
	}
	for _, e := range entries {
		docs, docErrs := s.messageDocs(e)
		report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
		report.Errors = append(report.Errors, docErrs...)
	}
	return report
}

// cachedTopologies returns the provider result — computed on first use or
// when force is set, reused otherwise. Concurrent requests share one
// computation. Entry paths are normalized to root-relative identifiers.
func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	if !s.topoLoaded || force {
		entries, errs := s.topo(ctx)
		s.topoEntries = make([]topology.Entry, 0, len(entries))
		for _, e := range entries {
			e.Path = s.relPath(e.Path)
			s.topoEntries = append(s.topoEntries, e)
		}
		s.topoErrs, s.topoLoaded = errs, true
	}
	return s.topoEntries, s.topoErrs
}

// topologiesLoaded reports whether the topology cache has been computed, and
// serves the cached result if it has. It never blocks on the computation:
// computing runs every host's graph verb (a dotnet build on first run) under
// one mutex, and the catalog endpoint must answer promptly rather than queue
// behind that. Instead the caller asks warmTopologies to compute in the
// background, so the pending answer becomes a matched one on the next fetch
// without anyone visiting the flow view first.
func (s *apiServer) topologiesLoaded() (loaded bool, entries []topology.Entry, errs []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	return s.topoLoaded, s.topoEntries, s.topoErrs
}

// warmTopologies triggers the topology computation in the background when the
// cache is cold. Only one warm-up runs at a time — cachedTopologies
// serialises on topoMu, and warming guards against stacking requests behind
// it. A detached context keeps the hosts' graph verbs running after the
// request that prompted them has been answered.
func (s *apiServer) warmTopologies() {
	s.topoMu.Lock()
	if s.topoLoaded || s.topoWarming {
		s.topoMu.Unlock()
		return
	}
	s.topoWarming = true
	s.topoMu.Unlock()

	go func() {
		defer func() {
			s.topoMu.Lock()
			s.topoWarming = false
			s.topoMu.Unlock()
		}()
		// The catalog requests that triggered this are already answered; the
		// computation is for the next one.
		_, _ = s.cachedTopologies(context.Background(), false)
	}()
}

// messageDocs reads the authored connector payload descriptions beside a
// system, keyed by connector name. A doc naming a connector the topology does
// not declare is surfaced as an error and withheld — never guessed around.
// Error messages carry the doc's workspace-relative path.
func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
	docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
	prefix := ""
	if e.Path != "." {
		prefix = e.Path + "/"
	}
	for i, msg := range errs {
		errs[i] = prefix + msg
	}
	known := map[string]bool{}
	for _, c := range e.Connectors {
		known[c.Name] = true
	}
	var unknown []string
	for name := range docs {
		if !known[name] {
			unknown = append(unknown, name)
			delete(docs, name)
		}
	}
	sort.Strings(unknown)
	for _, name := range unknown {
		errs = append(errs, fmt.Sprintf("%s%s/%s.md: no connector %q declared by system %q",
			prefix, messagesDirName, name, name, e.System))
	}
	if len(docs) == 0 {
		docs = nil
	}
	return docs, errs
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.enrich(e, systems)
	})
}

// getDeployState serves what the deploy status command last said about one
// integration, running it on the first request and reusing that until a POST to
// the same path. It is a separate endpoint from the integration detail because
// the two cost very different things: detail is local files, this refreshes a
// GitOps checkout over the network. Keeping them apart lets the detail panel
// render immediately and fill the deployment in when it arrives.
func (s *apiServer) getDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, false)
}

// refreshDeployState re-runs the command for one integration and returns the
// fresh result, picking up a deploy someone just made from another terminal.
func (s *apiServer) refreshDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, true)
}

func (s *apiServer) deployStateByPath(w http.ResponseWriter, r *http.Request, force bool) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.cachedDeployState(r.Context(), s.summarize(e, systems), force)
	})
}

// byPath resolves the {path...} wildcard to a scaffolded integration and serves
// what render makes of it, or 404s. Shared so the detail and deployment
// endpoints agree about which identifiers name the same integration.
func (s *apiServer) byPath(w http.ResponseWriter, r *http.Request, render func(template.ScaffoldEntry, map[string]string) any) {
	want := strings.Trim(r.PathValue("path"), "/")
	// An integration at the workspace root has the identifier "." (see
	// relPath), but a browser strips the "." segment from /api/integrations/.
	// so it arrives empty — treat the two as the same request.
	if want == "" {
		want = "."
	}
	entries, systems := s.scan()
	for _, e := range entries {
		if s.relPath(e.Path) == want {
			writeJSON(w, http.StatusOK, render(e, systems))
			return
		}
	}
	writeError(w, http.StatusNotFound, "integration not found: "+want)
}

// cachedDeployState returns one integration's deployment state — computed on
// first use or when force is set, reused otherwise.
//
// The mutex is held across the provider call rather than only around the map,
// because the command takes an exclusive lock on the shared GitOps checkout:
// two requests running it at once would have one of them fail on the other's
// lock. Serialising here turns that failure into a wait, and concurrent requests
// for the same integration share one run — the same bargain cachedTopologies
// makes with topoMu.
func (s *apiServer) cachedDeployState(ctx context.Context, sum integrationSummary, force bool) deployState {
	s.depMu.Lock()
	defer s.depMu.Unlock()

	if state, ok := s.depStates[sum.Path]; ok && !force {
		return state
	}

	ctx, cancel := context.WithTimeout(ctx, deployStateTimeout)
	defer cancel()
	state := s.dep(ctx, sum)

	if s.depStates == nil {
		s.depStates = map[string]deployState{}
	}
	s.depStates[sum.Path] = state
	return state
}

// enrich reads optional on-disk context for an integration. The entry's Path
// is already usable from the process working directory (see ListScaffolds), so
// it doubles as the project directory.
func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
	dir := e.Path
	return integrationDetail{
		integrationSummary: s.summarize(e, systems),
		Agents:             readDoc(dir, "AGENTS.md"),
		Readme:             readDoc(dir, "README.md"),
		Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
		PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
	}
}

// readDoc returns the named text file's (possibly truncated) contents, or nil
// if it is absent or unreadable.
func readDoc(dir, name string) *fileDoc {
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return nil
	}
	if len(data) > maxDocBytes {
		data = data[:maxDocBytes]
	}
	return &fileDoc{Name: name, Content: string(data)}
}

// listNames returns the sorted base names of the files directly under dir, or
// nil if dir is absent or unreadable.
func listNames(dir string) []string {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var names []string
	for _, ent := range ents {
		if !ent.IsDir() {
			names = append(names, ent.Name())
		}
	}
	sort.Strings(names)
	return names
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	_ = enc.Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

package main

import (
	"os"

	"github.com/spf13/cobra"
	"golang.org/x/term"
)

// deployCmd is a pure parent: the digest-pinning command lives at
// 'deploy pin', symmetric with 'release create'. Keeping deploy non-runnable
// means no component name is ever shadowed by a subcommand — a component
// called diff, init, pin, promote, status or sync deploys like any other.
var deployCmd = &cobra.Command{
	Use:   "deploy",
	Short: "Move components between environments via the GitOps repository",
	Long: "Pin image digests into environments, promote them along the environment graph, and review or " +
		"apply the pending result — all through the GitOps repository and ArgoCD, never kubectl.\n\n" +
		"  pin      Pin a component's image digest into an environment\n" +
		"  promote  Copy the digests one environment runs into another\n" +
		"  diff     Show the rendered change a sync would apply\n" +
		"  status   Show what every environment runs, side by side\n" +
		"  sync     Apply an environment's pending change through ArgoCD\n" +
		"  init     Scaffold a system's manifests into the GitOps repository",
}

// useColor decides whether to emit ANSI colour: only for a real terminal, and
// only if neither --no-color nor the de-facto NO_COLOR convention objects.
func useColor(cmd *cobra.Command) bool {
	if noColorFlag || os.Getenv("NO_COLOR") != "" {
		return false
	}
	f, ok := cmd.OutOrStdout().(*os.File)
	return ok && term.IsTerminal(int(f.Fd()))
}

func init() {
	rootCmd.AddCommand(deployCmd)
}

package gitops

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

const (
	// DeployFileName is the repository-level contract, at the root of the
	// GitOps repository. Its presence is what marks a repository as one this
	// CLI may deploy through.
	DeployFileName = "deploy.yaml"

	// ComponentFileName is the per-component contract, in the component
	// directory alongside base/ and overlays/.
	ComponentFileName = "component.yaml"

	// DomainsDirName is the root of the coordinate tree.
	DomainsDirName = "domains"

	// OverlaysDirName holds one directory per environment.
	OverlaysDirName = "overlays"

	// SchemaVersion is the newest schema this CLI understands for both files.
	// Bump only for incompatible changes; new optional fields do not require
	// a bump.
	SchemaVersion = 1

	// SyncAuto and SyncManual are the recognised environment sync policies.
	// Manual environments are gated in ArgoCD, so deploy commits and pushes
	// but must not wait for a sync that will never start on its own.
	SyncAuto   = "auto"
	SyncManual = "manual"

	// KindService and KindShared are the recognised component kinds.
	//
	// A service is a workload with an image for deploy to pin. A shared
	// component holds the system-level objects that belong to no single
	// workload — the Dapr components a system's blocks resolve by name, and the
	// secrets behind them. Exactly one ArgoCD Application must own each of
	// those objects, and a shared component is what gives them that owner.
	//
	// KindService is the default, so a component.yaml predating this field is
	// unchanged in meaning.
	KindService = "service"
	KindShared  = "shared"
)

// DeployConfig is the parsed deploy.yaml.
type DeployConfig struct {
	SchemaVersion int    `yaml:"schemaVersion"`
	Registry      string `yaml:"registry"`

	// MinimumCliVersion, when set, is the oldest CLI the repository's authors
	// consider safe to deploy with.
	MinimumCliVersion string `yaml:"minimumCliVersion"`

	// Platform describes the target cluster's hosting. It is repo-wide on
	// purpose: a system's Dapr components are identical in every environment,
	// so there is nothing for an environment to override. Only manifest
	// scaffolding reads it; deploy, promote, diff and sync ignore it entirely.
	Platform PlatformConfig `yaml:"platform"`

	Argocd       ArgocdConfig                 `yaml:"argocd"`
	Environments map[string]EnvironmentConfig `yaml:"environments"`
}

// PlatformConfig names the hosting choices a manifest skeleton renders against.
//
// The values are deliberately not validated here. The allowed set belongs to
// whichever template consumes them — its JSON Schema is where the enum lives —
// and hard-coding a list here would mean a CLI release for every new broker.
type PlatformConfig struct {
	// Provider is the hosting environment, e.g. "azure" or "beebyte".
	Provider string `yaml:"provider"`

	// Pubsub selects the Dapr pub/sub building block, e.g. "in-memory",
	// "rabbitmq" or "servicebus".
	Pubsub string `yaml:"pubsub"`

	// SecretStore selects the Dapr secret store, e.g. "kubernetes",
	// "azure.keyvault" or "vault".
	SecretStore string `yaml:"secretStore"`
}

// ArgocdConfig locates the ArgoCD instance that reconciles this repository.
type ArgocdConfig struct {
	Server string `yaml:"server"`

	// AppNamespace is the namespace the Application objects live in. It is not
	// optional in practice: the ApplicationSets are deployed per customer
	// (e.g. customer-wsf) rather than into argocd, and omitting appNamespace
	// from an API call against such an installation returns a 404 that is
	// indistinguishable from "no such application".
	AppNamespace string `yaml:"appNamespace"`
}

// EnvironmentConfig is one entry under environments.
type EnvironmentConfig struct {
	// Sync is "auto" or "manual".
	Sync string `yaml:"sync"`

	// PromotesFrom lists environments a promotion into this one may draw
	// from. Deploy reads it to report whether the digests being deployed are
	// what those environments already run; enforcing it is the promote
	// command's job.
	PromotesFrom []string `yaml:"promotesFrom"`

	// RequireSourceHealthy demands the source environment be healthy before a
	// promotion into this one. Parsed here, enforced by promote.
	RequireSourceHealthy bool `yaml:"requireSourceHealthy"`

	// Scratch marks an environment as disposable. The semantics are not yet
	// defined, so this is carried but never acted on — parsing it now means a
	// repository that already sets it is not rejected as malformed.
	Scratch bool `yaml:"scratch"`
}

// ComponentConfig is the parsed component.yaml.
type ComponentConfig struct {
	SchemaVersion int    `yaml:"schemaVersion"`
	Name          string `yaml:"name"`

	// Kind is KindService or KindShared; empty means KindService, so every
	// component.yaml written before this field existed keeps working.
	Kind string `yaml:"kind"`

	// SourcePaths are the paths in the *source* repository that make up this
	// component. The working-tree cleanliness check is scoped to them, so an
	// unrelated dirty file elsewhere in a monorepo does not block a deploy.
	SourcePaths []string `yaml:"sourcePaths"`

	// Images are the image repositories to pin. Explicit rather than derived:
	// existing repositories name images inconsistently, and a wrong guess
	// silently adds an inert images[] entry instead of failing.
	Images []ImageRef `yaml:"images"`

	// Environments are the environments this component may deploy to.
	Environments []string `yaml:"environments"`
}

// ImageRef names one image repository, without a tag or digest.
type ImageRef struct {
	Name string `yaml:"name"`
}

// LoadDeployConfig reads and validates deploy.yaml from the root of a GitOps
// repository.
func LoadDeployConfig(root string) (*DeployConfig, error) {
	path := filepath.Join(root, DeployFileName)
	var cfg DeployConfig
	if err := decodeFile(path, &cfg); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("%s has no %s, so it is not a GitOps repository this CLI can deploy through", root, DeployFileName)
		}
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *DeployConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Registry == "" {
		return fmt.Errorf("%s: registry is required", path)
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	for _, name := range slices.Sorted(maps.Keys(c.Environments)) {
		env := c.Environments[name]
		switch env.Sync {
		case SyncAuto, SyncManual:
		case "":
			return fmt.Errorf("%s: environment %q has no sync policy (expected %q or %q)", path, name, SyncAuto, SyncManual)
		default:
			return fmt.Errorf("%s: environment %q has sync %q (expected %q or %q)", path, name, env.Sync, SyncAuto, SyncManual)
		}
		for _, src := range env.PromotesFrom {
			if _, ok := c.Environments[src]; !ok {
				return fmt.Errorf("%s: environment %q promotes from %q, which is not defined", path, name, src)
			}
		}
	}
	return nil
}

// Environment returns the named environment's policy, or an error listing the
// environments the repository does define.
func (c *DeployConfig) Environment(name string) (EnvironmentConfig, error) {
	env, ok := c.Environments[name]
	if !ok {
		return EnvironmentConfig{}, fmt.Errorf("unknown environment %q; %s defines: %s", name, DeployFileName, strings.Join(c.EnvironmentNames(), ", "))
	}
	return env, nil
}

// EnvironmentNames returns the defined environment names in sorted order.
func (c *DeployConfig) EnvironmentNames() []string {
	return slices.Sorted(maps.Keys(c.Environments))
}

// PromotionOrder returns the environments in the order changes flow through
// them: an environment comes after every environment it promotes from. Ties
// break alphabetically, so the order is stable across runs.
//
// EnvironmentNames sorts alphabetically, which renders the usual three as dev,
// prod, staging. That is the wrong story for anything presenting environments
// as a pipeline — the promotion graph is what says prod comes last.
func (c *DeployConfig) PromotionOrder() []string {
	// Sources counts the not-yet-emitted environments each one promotes from.
	// An edge naming an undefined environment is impossible here: validate
	// rejects the file first.
	remaining := make(map[string]int, len(c.Environments))
	for name, env := range c.Environments {
		sources := 0
		for _, src := range env.PromotesFrom {
			// A self-edge is not a dependency on anything else, and counting it
			// would make the environment permanently unemittable.
			if src != name {
				sources++
			}
		}
		remaining[name] = sources
	}

	order := make([]string, 0, len(c.Environments))
	for len(remaining) > 0 {
		ready := make([]string, 0, len(remaining))
		for name, sources := range remaining {
			if sources == 0 {
				ready = append(ready, name)
			}
		}

		// Nothing is ready, so the remainder is a cycle. deploy.yaml's
		// validation does not forbid one, and dropping those environments would
		// hide them from a caller listing what exists — emit them alphabetically
		// instead.
		if len(ready) == 0 {
			order = append(order, slices.Sorted(maps.Keys(remaining))...)
			break
		}

		slices.Sort(ready)
		order = append(order, ready...)
		for _, name := range ready {
			delete(remaining, name)
		}
		// Emitting a whole rank at a time keeps siblings adjacent and
		// alphabetical, rather than interleaving them by discovery order.
		for _, name := range ready {
			for other, env := range c.Environments {
				if _, pending := remaining[other]; !pending {
					continue
				}
				for _, src := range env.PromotesFrom {
					if src == name {
						remaining[other]--
					}
				}
			}
		}
	}
	return order
}

// LoadComponentConfig reads and validates a component.yaml from a component
// directory.
func LoadComponentConfig(dir string) (*ComponentConfig, error) {
	path := filepath.Join(dir, ComponentFileName)
	var cfg ComponentConfig
	if err := decodeFile(path, &cfg); err != nil {
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *ComponentConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Name == "" {
		return fmt.Errorf("%s: name is required", path)
	}
	switch c.Kind {
	case "", KindService, KindShared:
	default:
		return fmt.Errorf("%s: kind %q is not valid (expected %q or %q)", path, c.Kind, KindService, KindShared)
	}
	if c.IsShared() {
		// An images entry that matches nothing is inert rather than fatal, so a
		// shared component listing one would look pinnable and never be pinned.
		if len(c.Images) > 0 {
			return fmt.Errorf("%s: kind %q must not declare images — there is no workload to pin", path, KindShared)
		}
	} else if len(c.Images) == 0 {
		return fmt.Errorf("%s: at least one entry under images is required — there is nothing to pin otherwise", path)
	}
	for i, img := range c.Images {
		if img.Name == "" {
			return fmt.Errorf("%s: images[%d] has no name", path, i)
		}
		if hasTagOrDigest(img.Name) {
			return fmt.Errorf("%s: images[%d] name %q must be a bare repository, without a tag or digest", path, i, img.Name)
		}
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	return nil
}

// SupportsEnvironment reports whether the component declares env.
func (c *ComponentConfig) SupportsEnvironment(env string) bool {
	return slices.Contains(c.Environments, env)
}

// IsShared reports whether the component holds system-level objects rather than
// a workload, and so has nothing for deploy or promote to pin.
func (c *ComponentConfig) IsShared() bool {
	return c.Kind == KindShared
}

// hasTagOrDigest reports whether an image reference carries a tag or digest.
//
// Only the final path segment is examined, because a colon earlier in the
// reference is a registry port: localhost:5555/integrations/app and
// harbor.example.com:8443/app are perfectly ordinary repositories, and
// rejecting them would rule out every registry not on the default port.
func hasTagOrDigest(image string) bool {
	last := image
	if i := strings.LastIndex(image, "/"); i >= 0 {
		last = image[i+1:]
	}
	return strings.ContainsAny(last, ":@")
}

func checkSchemaVersion(path string, got int) error {
	switch {
	case got == 0:
		return fmt.Errorf("%s: schemaVersion is required", path)
	case got > SchemaVersion:
		return fmt.Errorf("%s: schemaVersion %d is newer than this CLI supports (%d); upgrade intropy", path, got, SchemaVersion)
	case got < 1:
		return fmt.Errorf("%s: schemaVersion %d is not valid", path, got)
	}
	return nil
}

// decodeFile decodes a YAML file, rejecting unknown fields so that a
// misspelled key is a loud error rather than a setting that silently does
// nothing.
func decodeFile(path string, into any) error {
	f, err := os.Open(path)
	if err != nil {
		// Wrapped, so callers can still test for fs.ErrNotExist.
		return fmt.Errorf("read %s: %w", path, err)
	}
	defer f.Close()

	dec := yaml.NewDecoder(f)
	dec.KnownFields(true)
	if err := dec.Decode(into); err != nil {
		if errors.Is(err, io.EOF) {
			return fmt.Errorf("parse %s: file is empty", path)
		}
		return fmt.Errorf("parse %s: %w", path, err)
	}
	return nil
}

