// Package gitopstest builds GitOps repository fixtures for tests.
//
// It deliberately does not import gitops. The packages under test have
// internal test files (package gitops, package deploy), so importing gitops
// here would create a cycle — and spelling the layout out in literals is
// better anyway: a test that derives its expectations from the code under test
// cannot catch that code changing the layout.
package gitopstest

import (
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/gittest"
)

// DeployYAML is a valid deploy.yaml covering all three sync shapes: an
// automatic environment, one that promotes, and a manual one with a health
// requirement.
const DeployYAML = `schemaVersion: 1
registry: harbor.intropy.io
argocd:
  server: argocd.intropy.io
  appNamespace: customer-fluxia
environments:
  dev:
    sync: auto
  staging:
    sync: auto
    promotesFrom: [dev]
  prod:
    sync: manual
    promotesFrom: [staging]
    requireSourceHealthy: true
`

// BaseDeployment is a Deployment whose container image is the literal IMAGE,
// for callers to substitute.
const BaseDeployment = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: order-extractor
spec:
  replicas: 1
  selector:
    matchLabels:
      app: order-extractor
  template:
    metadata:
      labels:
        app: order-extractor
    spec:
      containers:
        - name: app
          image: IMAGE:latest
`

// ComponentYAML renders a component.yaml.
func ComponentYAML(name, image string, envs []string) string {
	return "schemaVersion: 1\nname: " + name +
		"\nsourcePaths: [component/]\nimages:\n  - name: " + image +
		"\nenvironments: [" + strings.Join(envs, ", ") + "]\n"
}

// Component describes one component to place in a fixture repository.
type Component struct {
	// Coordinate is "domain/system/component".
	Coordinate string

	// Image is the repository component.yaml declares and the base references.
	Image string

	// Environments are the overlays to create, and the environments
	// component.yaml declares.
	Environments []string

	// OverlayImages is the images[]/commonAnnotations block appended to the
	// first environment's kustomization.yaml. Empty leaves the overlay
	// unpinned, which is the state most existing repositories are in.
	OverlayImages string
}

// NewRepo creates a git repository laid out as a GitOps repository, with one
// commit containing every component given.
func NewRepo(t *testing.T, components ...Component) string {
	t.Helper()
	root := t.TempDir()
	gittest.Init(t, root, "main")
	gittest.WriteFile(t, filepath.Join(root, "deploy.yaml"), DeployYAML)

	for _, c := range components {
		parts := strings.Split(c.Coordinate, "/")
		if len(parts) != 3 {
			t.Fatalf("coordinate %q must be domain/system/component", c.Coordinate)
		}
		image := c.Image
		if image == "" {
			image = "harbor.intropy.io/integrations/" + parts[2]
		}
		envs := c.Environments
		if len(envs) == 0 {
			envs = []string{"dev"}
		}

		dir := filepath.Join(root, "domains", parts[0], parts[1], parts[2])
		gittest.WriteFile(t, filepath.Join(dir, "component.yaml"), ComponentYAML(parts[2], image, envs))
		gittest.WriteFile(t, filepath.Join(dir, "base", "deployment.yaml"),
			strings.ReplaceAll(BaseDeployment, "IMAGE", image))
		gittest.WriteFile(t, filepath.Join(dir, "base", "kustomization.yaml"),
			"apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nresources:\n  - deployment.yaml\n")

		for i, env := range envs {
			overlay := "apiVersion: kustomize.config.k8s.io/v1beta1\nkind: Kustomization\nnamespace: integrations\nresources:\n  - ../../base\n"
			if i == 0 {
				overlay += c.OverlayImages
			}
			gittest.WriteFile(t, filepath.Join(dir, "overlays", env, "kustomization.yaml"), overlay)
		}
	}

	gittest.Run(t, root, "add", ".")
	gittest.Run(t, root, "commit", "--quiet", "-m", "onboard components")
	return root
}

import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration } from './api'
import { Sidebar } from './components/Sidebar'
import { Catalog } from './components/Catalog'
import { FlowView } from './components/FlowView'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the catalog entry
  // is local files plus a cached topology. Keeping them apart lets the page
  // render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' ? (
            <Catalog
              path={selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          ) : (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

// Types mirror the Go JSON contract served by `intropy dashboard`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

/** A dependency another template rendered alongside this integration. */
export interface DependencyRecord {
  template: string
  /** Slash-separated directory relative to the component root. */
  dir: string
}

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  /** Which way data crosses the system boundary, declared by the template
   *  (intropy.dev/data-flow label) and recorded in scaffold.json. */
  dataFlow?: 'in' | 'out' | 'both' | 'internal'
  /** Topology block kind the template scaffolds (intropy.dev/block-kind
   *  label), e.g. "extractor" or "loader". */
  blockKind?: string
  /** Support-project role (intropy.dev/template-role label). Projects with a
   *  role (system-host, shared-library) are filtered out of the catalog by
   *  the server; the field only appears on records read elsewhere. */
  role?: string
  /** Sibling projects this integration's template rendered as dependencies. */
  dependsOn?: DependencyRecord[]
  values: Record<string, unknown>
  /** Directory carrying the .intropy record; the integration's display name. */
  name: string
  /** Parent directory of the integration; absent directly under the root. */
  system?: string
  /** Parent directory of the system; absent when the system sits at the root. */
  domain?: string
  /** Root-relative directory of the system ("." when rooted at the workspace).
   *  The unique system key — two directories can declare the same `system`
   *  name — and the join key to a declared Topology's `path`. */
  systemPath?: string
}

export interface FileDoc {
  name: string
  content: string
}

/** A parsed Dapr component. `category` decides where the flow canvas draws it:
 *  `pubsub`/`state` inside the system boundary, `binding` outside — as a
 *  source when `direction` is `input`, a sink otherwise. */
export interface DaprComponent {
  name: string
  type: string
  category: 'pubsub' | 'state' | 'binding' | 'other'
  /** Normalized `direction` metadata from the component spec. Absent when
   *  undeclared — treated as unknown (rendered as a sink), never inferred. */
  direction?: 'input' | 'output' | 'input,output'
  file: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  components?: DaprComponent[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
}

// Deployment state (internal/deploy). The server obtains each record by running
// the `deploy status` command with a JSON writer and passing its result through
// unchanged, so everything below is that command's own output — including the
// prose in `summary` and `notes`, which must be rendered as served rather than
// re-derived from `environments`.

/** How one overlay pins one image. */
export interface ResultPin {
  image: string
  /** The digest this replaced. Only present on a deployment's own result. */
  previous?: string
  digest: string
  /** The tag the digest was resolved from, or the tag pinned instead of a
   *  digest. Empty when the digest came from a release manifest. */
  tag?: string
}

/** One environment's row of the deployment ladder. */
export interface EnvironmentStatus {
  environment: string
  appName: string
  overlayPath: string
  /** False means there is no readable overlay here; `reason` says why and
   *  everything below is empty. On its own it never means "not deployed". */
  onboarded: boolean
  reason?: string
  /** The version this environment runs. Absent when it was deployed from a
   *  commit rather than a release, in which case `sourceCommit` stands in. */
  release?: string
  sourceCommit?: string
  /** Every image the component declares, in declared order. `digest` is empty
   *  when the overlay pins a tag or nothing — `tag` says which. */
  pins?: ResultPin[]
  /** The GitOps commit that last changed this overlay, and when it landed.
   *  Both absent when the overlay path has no history. */
  revision?: string
  /** RFC 3339. */
  deployedAt?: string
  syncPolicy: 'auto' | 'manual' | string
  /** What ArgoCD reports. Absent when it could not be read — which says
   *  nothing at all about what the overlay pins. */
  syncStatus?: string
  healthStatus?: string
  syncedRevision?: string
  /** What ArgoCD observed running in the cluster, as opposed to what the
   *  overlay pins. Absent under the same rule as `syncStatus`: its absence
   *  says nothing about the overlay or the cluster. */
  liveImages?: string[]
  /** A committed overlay change ArgoCD has not applied. For a `manual`
   *  environment that is an unspent gate at rest, not a fault. */
  pending: boolean
}

export interface StatusResult {
  component: string
  domain: string
  system: string
  /** Declared kind. "shared" holds system-level manifests and no image, so its
   *  empty digests are by design rather than evidence of never deploying. */
  kind: 'service' | 'shared' | string
  /** In promotion order: the last entry is the furthest downstream. */
  environments: EnvironmentStatus[]
  /** Every onboarded environment pins the identical digest for every image —
   *  what makes "prod runs the bits staging tested" a fact. */
  consistent: boolean
  /** The command's own sentence about what the environments collectively run.
   *  Render as served: `consistent` is a bool and the interesting cases are
   *  not — "these run different bits" and "there is nothing to compare" are
   *  both false and mean very different things. */
  summary: string
  /** The command's qualifications: an environment that could not be read, one
   *  pinning a tag, one waiting on a sync gate. */
  notes?: string[]
  /** The promotion graph restricted to this component's environments: for each
   *  environment, the ones a promotion into it may draw from. Carried on the
   *  result because deploy.yaml lives in the GitOps repository, which a
   *  consumer without a session cannot read. */
  promotesFrom?: Record<string, string[]>
}

// Catalog entry (internal/dashboard/catalog.go). Header identity and contracts
// come from the cached system topology when it has the component, and from the
// scaffold record — provenance only, it can go stale — otherwise. Deployment
// state is deliberately not embedded; it stays on /api/deploy/{path}, which
// costs a GitOps checkout refresh.

/** One end of a pub/sub wire a component sits on. */
export interface ContractEdge {
  pubsub: string
  topic: string
  /** The topic's contract shortName when the registry carries it, the raw
   *  contract name otherwise — the flow view's lookup rule. */
  contract?: string
  /** Every component the topic declares on each end of the wire — a contract
   *  shown as the connection between components, not a name. */
  publishers?: string[]
  subscribers?: string[]
}
/** One finding about the integration's place in the system graph. */
export interface CatalogCheck {
  severity: 'warn' | 'info'
  message: string
}

/** Why contracts are unknown, when they are: the catalog's join of the
 *  integration against its system's declared graph. */
export type GraphStatus =
  | 'matched'
  | 'no-topology'
  | 'not-in-graph'
  | 'topology-error'
  | 'pending'

export interface CatalogEntry {
  /** Graph name when matched, scaffold record name otherwise. */
  component: string
  /** Topology block kind; absent in every non-matched state. */
  kind?: string
  system?: string
  /** System directory the topology record joins on — for matching the
   *  contract registry when fetching /api/topology. */
  systemPath?: string
  publishes?: ContractEdge[]
  subscribes?: ContractEdge[]
  /** "owner/repo" from the scaffold record — provenance only. */
  repository?: string
  graphStatus: GraphStatus
  /** True while the first topology computation is in flight: the header
   *  renders from scaffold data and contracts are unknown. */
  topologyPending?: boolean
  /** Graph-derived findings, warns before infos. */
  checks?: CatalogCheck[]
}

/** The /api/deploy/{path} payload: what the deploy status command said about one
 *  integration, or why it could not say anything. */
export interface DeployState {
  status?: StatusResult
  /** The command's message, verbatim — an unconfigured GitOps repository, a
   *  component name matching several, a checkout another deploy is holding.
   *  None of these is a statement about the integration; only `status` is. */
  error?: string
  /** What the command wrote to stderr: which repository it refreshed, and any
   *  environment ArgoCD could not be read for. Provenance, not failure. */
  diagnostics?: string[]
  /** RFC 3339 — when the command ran. */
  readAt: string
}

// Declared system topology (internal/topology). The server obtains each
// record by running the system host's `graph` verb (apiVersion
// topology.intropy.io/v1) and caches the result until an explicit refresh.
// Wiring is inlined on each component — the topics it subscribes to and
// publishes on and the connectors it uses — while the top-level `topics` and
// `connectors` sections are the lookup tables those inline references resolve
// against. There is no fallback: a system whose host cannot produce a record
// appears in `errors` instead of `topologies`.

/** A component's subscription to a pub/sub topic. */
export interface TopicRef {
  pubsub: string
  topic: string
}

/** A component's output onto a pub/sub topic. */
export interface Publication {
  /** Component output port the message leaves through. */
  port?: string
  pubsub: string
  topic: string
}

/** A component's use of an external connector. */
export interface ConnectorUse {
  connector: string
  /** "in" (external → component) or "out" (component → external). */
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block type: extractor, loader, transactionalIntegration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  connectors?: ConnectorUse[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  provides?: unknown[]
  consumes?: unknown[]
}

/** A declared pub/sub topic: metadata for a (pubsub, topic) pair components
 *  reference. */
export interface TopologyTopic {
  pubsub: string
  topic: string
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

/** An external system integration point. The name is its whole identity —
 *  the deployed Dapr binding type is environment-owned deployment
 *  configuration, never part of the record. */
export interface TopologyConnector {
  name: string
  externalSystem?: string
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

/** A message contract in the system's registry, keyed by `name` — the same
 *  fully-qualified type name TopologyTopic.contract references. */
export interface Contract {
  name: string
  /** "event" for pub/sub message contracts. */
  kind?: string
  /** Bare type name — the join key to a scaffold record's values.contract. */
  shortName?: string
  mediaType?: string
  /** Hash of the schema's canonical form; equal fingerprints mean equal
   *  shapes across systems. */
  fingerprint?: string
  /** JSON Schema as the host emitted it, passed through verbatim. */
  schema?: JsonSchema
}

/** The subset of JSON Schema the contract field tree renders. Anything it
 *  does not recognize falls back to a raw type label, never an error. */
export interface JsonSchema {
  type?: string | string[]
  format?: string
  properties?: Record<string, JsonSchema>
  required?: string[]
  items?: JsonSchema
  enum?: unknown[]
  $ref?: string
  $defs?: Record<string, JsonSchema>
}

/** One field or column of an external payload, as its author described it.
 *  `type` is loose by design — documentation, not a validatable schema. */
export interface MessageDocField {
  name: string
  position?: number
  type?: string
  required?: boolean
  notes?: string
}

/** A short inline payload excerpt. The server only serves samples whose
 *  author explicitly asserted the redaction check. */
export interface MessageDocSample {
  inline: string
  redacted?: boolean
}

/** An authored description of the payload a connector carries (the flat file
 *  from an SFTP drop, the ad-hoc CSV export), read from the system's
 *  messages/<connector>.md sidecar. Documentation, not enforcement. */
export interface MessageDoc {
  format?: string
  delimiter?: string
  encoding?: string
  filePattern?: string
  frequency?: string
  contact?: string
  lastReviewed?: string
  fields?: MessageDocField[]
  sample?: MessageDocSample
  /** Free prose from the doc's Markdown body. */
  body?: string
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  apiVersion: string
  kind?: string
  /** System name (a bare string in v1). */
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  connectors?: TopologyConnector[]
  /** Message contract registry topics reference by contract name. Absent
   *  until the system host's topology library emits it. */
  contracts?: Contract[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  apis?: unknown[]
  /** Authored connector payload descriptions, keyed by connector name.
   *  CLI-merged enrichment from messages/<connector>.md — not part of the
   *  host-declared topology, and re-read on every request. */
  messageDocs?: Record<string, MessageDoc>
}

/** The /api/topology payload: every declared topology plus the per-host
 *  failures (a host whose graph verb failed, e.g. because it pre-dates the
 *  verb or does not build). */
export interface TopologyReport {
  topologies: Topology[]
  errors?: string[]
}

async function requestJSON<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    throw new Error(message)
  }
  return (await res.json()) as T
}

const getJSON = <T,>(url: string) => requestJSON<T>(url)

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  /** Every integration enriched with pipeline steps + Dapr components for the flow canvas. */
  flow: () => getJSON<IntegrationDetail[]>('/api/flow'),
  /** Every declared system topology, cached from the hosts' graph verbs. */
  topologies: () => getJSON<TopologyReport>('/api/topology'),
  /** Re-run every host's graph verb and return the fresh report. */
  refreshTopologies: () =>
    requestJSON<TopologyReport>('/api/topology/refresh', { method: 'POST' }),
  /** One integration's catalog entry: header facts and graph-derived checks. */
  catalog: (path: string) => getJSON<CatalogEntry>(`/api/catalog/${path}`),
  /** One integration's deployment state, read once and reused by the server. */
  deployState: (path: string) => getJSON<DeployState>(`/api/deploy/${path}`),
  /** Re-run `deploy status` for one integration and return the fresh result —
   *  how you pick up a deploy just made from another terminal. */
  refreshDeployState: (path: string) =>
    requestJSON<DeployState>(`/api/deploy/${path}`, { method: 'POST' }),
  health: () => getJSON<Health>('/api/health'),
}

import { useEffect, useMemo, useState } from 'react'
import {
  Background,
  Controls,
  Handle,
  MarkerType,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useNodesInitialized,
  useNodesState,
  useReactFlow,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  api,
  type DaprComponent,
  type IntegrationDetail,
  type Topology,
  type TopologyReport,
} from '../api'
import {
  CloudIcon,
  CycleIcon,
  HardDriveIcon,
  HubIcon,
  InputIcon,
  MemoryIcon,
  OutputIcon,
  SyncAltIcon,
} from '../icons'
import { Combobox, type ComboOption } from './Combobox'
import { FlowDetail, type FlowSelection } from './FlowDetail'

interface Props {
  selected: string | null
  onSelect: (path: string) => void
  /** Resolved app theme; drives React Flow's chrome (controls, minimap, edges). */
  theme: 'light' | 'dark'
}

// Layout geometry. The layout is deterministic: components and the topics
// they publish/subscribe flow left-to-right by declared depth inside the
// system boundary, and external systems (via connectors) sit outside it.
const NODE_W = 300
const NODE_H = 84
const COL_GAP = 28
const ROW_GAP = 28
const GROUP_HEADER = 44
const GROUP_PAD = 20
const INFRA_W = 200
const INFRA_H = 76
const EXT_W = 184
const EXT_H = 72
const EXT_GAP = 96
const EXT_VGAP = 24

const WORKSPACE_KEY = '__workspace__'

/** Which way data crosses the system boundary for a component. */
type DataFlow = 'in' | 'out' | 'both' | 'internal'

// Boundary direction by declared component kind, used only to pick the card's
// directional glyph — never to invent wiring; every edge on the canvas comes
// from the declared topology.
const KIND_DATA_FLOW: Record<string, DataFlow> = {
  extractor: 'in',
  loader: 'out',
  transactional: 'both',
  transactionalintegration: 'both',
  aggregator: 'internal',
}

// dataFlowFor resolves a component kind to its boundary direction, ignoring
// case and hyphens (the topology library kebab-cases kinds, e.g.
// "transactional-integration").
function dataFlowFor(kind: string): DataFlow | undefined {
  return KIND_DATA_FLOW[kind.toLowerCase().replace(/-/g, '')]
}

// Directional glyph per data flow; integrations with no known flow keep the
// generic chip icon rather than guessing a direction.
const DATA_FLOW_ICONS: Record<DataFlow, typeof MemoryIcon> = {
  in: InputIcon,
  out: OutputIcon,
  both: SyncAltIcon,
  internal: CycleIcon,
}

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  dataFlow?: DataFlow
  selected: boolean
  /** Cron expression badge for schedule-triggered components (declared topology only). */
  trigger?: string
}

interface GroupNodeData extends Record<string, unknown> {
  title: string
  count: number
}

interface ExtNodeData extends Record<string, unknown> {
  name: string
  type: string
  direction?: DaprComponent['direction']
  /** Declared connector name — the inspector's join key to the topology's
   *  connectors[] and messageDocs. */
  connector?: string
}

interface TopicNodeData extends Record<string, unknown> {
  name: string
  /** Pub/sub component the topic lives on — with name, the inspector's join
   *  key into the topology's topics[]. */
  pubsub?: string
  /** Data entity carried on the topic, e.g. "RawProduct". */
  entity?: string
  /** Contract ref when the topic is a declared API (contract surface). */
  contract?: string
}

// systemKey identifies a system by its root directory, the one grouping key
// that stays unique when two directories declare the same system name (e.g. a
// copied system). Integrations scaffolded at the workspace root fall under a
// "Workspace" pseudo-system.
function systemKey(it: IntegrationDetail): string {
  return it.systemPath || WORKSPACE_KEY
}

function systemLabel(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join(' / ') || 'Workspace'
}

// topologyFor picks the declared topology for a system: the record its host
// produced, which carries the system directory as its path. The Workspace
// pseudo-system maps to a record at the root ('.').
function topologyFor(key: string, topologies: Topology[]): Topology | undefined {
  const path = key === WORKSPACE_KEY ? '.' : key
  return topologies.find((t) => t.path === path)
}

export function FlowView({ selected, onSelect, theme }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [report, setReport] = useState<TopologyReport | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [refreshing, setRefreshing] = useState(false)
  const [system, setSystem] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])
  // What the inspector panel shows: a clicked topic or connector node.
  const [inspect, setInspect] = useState<FlowSelection | null>(null)

  // A different system means different topics/connectors — drop the inspector.
  useEffect(() => setInspect(null), [system])

  useEffect(() => {
    const fail = (e: unknown) => setError(e instanceof Error ? e.message : String(e))
    api.flow().then(setGraph).catch(fail)
    // The first topology fetch runs each host's graph verb (a dotnet build),
    // so this request can take a while — the loading state covers it.
    api.topologies().then(setReport).catch(fail)
  }, [])

  const refresh = () => {
    setRefreshing(true)
    api
      .refreshTopologies()
      .then(setReport)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRefreshing(false))
  }

  const topologies = useMemo(() => report?.topologies ?? [], [report])

  // The dropdown lists every system present, with an integration count. When
  // a declared topology covers a group its system name is the authoritative
  // label, overriding the folder-derived one. Systems that end up sharing a
  // label are qualified with their directory so the options stay tellable
  // apart — the underlying keys are always distinct.
  const systems = useMemo<ComboOption[]>(() => {
    if (!graph) return []
    const opts = new Map<string, ComboOption>()
    for (const it of graph) {
      const key = systemKey(it)
      const opt = opts.get(key) ?? { value: key, label: systemLabel(it), count: 0 }
      opt.count = (opt.count ?? 0) + 1
      opts.set(key, opt)
    }
    for (const opt of opts.values()) {
      const t = topologyFor(opt.value, topologies)
      if (t) opt.label = t.system
    }
    const byLabel = new Map<string, ComboOption[]>()
    for (const opt of opts.values()) {
      byLabel.set(opt.label, [...(byLabel.get(opt.label) ?? []), opt])
    }
    for (const dup of byLabel.values()) {
      if (dup.length > 1) for (const opt of dup) opt.label = `${opt.label} (${opt.value})`
    }
    return [...opts.values()].sort((a, b) => a.label.localeCompare(b.label))
  }, [graph, topologies])

  // Default to the first system once data lands.
  useEffect(() => {
    if (system === null && systems.length > 0) setSystem(systems[0].value)
  }, [systems, system])

  const items = useMemo(
    () => (graph && system ? graph.filter((it) => systemKey(it) === system) : []),
    [graph, system],
  )

  // Only a declared topology is drawn — there is no inferred fallback. A
  // system whose host produced no record renders the empty state below.
  const declared = useMemo(
    () => (system ? topologyFor(system, topologies) : undefined),
    [system, topologies],
  )
  const built = useMemo(
    () => (declared ? buildDeclaredGraph(declared, items) : { nodes: [], edges: [] }),
    [declared, items],
  )
  useEffect(() => setNodes(built.nodes), [built, setNodes])

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph || report === null) {
    return <p className="empty">Loading… (building system hosts on first run)</p>
  }
  if (graph.length === 0) {
    return <p className="empty">No integrations to visualise.</p>
  }

  return (
    <div className="flow-view">
      <div className="flow-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={systems}
          onChange={setSystem}
          placeholder="Select a system…"
        />
        <button
          type="button"
          className="flow-refresh"
          onClick={refresh}
          disabled={refreshing}
          title="Re-run each system host's graph verb"
        >
          {refreshing ? 'Refreshing…' : 'Refresh topology'}
        </button>
      </div>
      {report.errors?.length ? (
        <div className="banner error">
          {report.errors.map((e) => (
            <div key={e}>{e}</div>
          ))}
        </div>
      ) : null}
      {declared ? (
        <div className="flow-canvas">
          <ReactFlowProvider>
            <FlowCanvas
              nodes={nodes}
              edges={built.edges}
              onNodesChange={onNodesChange}
              onSelect={onSelect}
              onInspect={setInspect}
              fitSignal={system ?? ''}
              theme={theme}
            />
          </ReactFlowProvider>
          {inspect && (
            <FlowDetail
              selection={inspect}
              topology={declared}
              onClose={() => setInspect(null)}
            />
          )}
        </div>
      ) : (
        <p className="empty">
          No declared topology for this system. Make sure its system host
          supports the graph verb, then refresh.
        </p>
      )}
    </div>
  )
}

// FlowCanvas hosts the React Flow instance so it can refit the viewport once
// nodes are measured, and again whenever the selected system changes — the
// `fitView` prop alone fits at init while the async node list is still empty.
function FlowCanvas({
  nodes,
  edges,
  onNodesChange,
  onSelect,
  onInspect,
  fitSignal,
  theme,
}: {
  nodes: Node[]
  edges: Edge[]
  onNodesChange: Parameters<typeof ReactFlow>[0]['onNodesChange']
  onSelect: (path: string) => void
  onInspect: (selection: FlowSelection | null) => void
  fitSignal: string
  theme: 'light' | 'dark'
}) {
  const rf = useReactFlow()
  const initialized = useNodesInitialized()

  useEffect(() => {
    if (initialized) rf.fitView({ padding: 0.2 })
  }, [initialized, fitSignal, rf])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      nodeTypes={NODE_TYPES}
      colorMode={theme}
      minZoom={0.3}
      proOptions={{ hideAttribution: true }}
      onNodeClick={(_, node) => {
        if (node.type === 'integration') onSelect(node.id)
        if (node.type === 'topic') {
          const d = node.data as TopicNodeData
          if (d.pubsub) onInspect({ kind: 'topic', pubsub: d.pubsub, topic: d.name })
        }
        if (node.type === 'external') {
          const d = node.data as ExtNodeData
          if (d.connector) onInspect({ kind: 'connector', name: d.connector })
        }
      }}
      onPaneClick={() => onInspect(null)}
    >
      <Background gap={20} />
      <Controls showInteractive={false} />
      <MiniMap pannable zoomable />
    </ReactFlow>
  )
}


// refName extracts the display name from an entity ref: "component:pim-extractor"
// → "pim-extractor", "system:default/pim" → "pim".
function refName(ref: string): string {
  const rest = ref.slice(ref.indexOf(':') + 1)
  const slash = rest.lastIndexOf('/')
  return slash >= 0 ? rest.slice(slash + 1) : rest
}

// buildDeclaredGraph renders a system's declared topology (v1): components and
// the topics they publish/subscribe laid out left-to-right by flow depth
// inside the boundary, external systems (via connectors) outside it. Nothing
// here is inferred — every node and edge comes straight from the record's
// inline wiring.
function buildDeclaredGraph(
  topo: Topology,
  items: IntegrationDetail[],
): { nodes: Node[]; edges: Edge[] } {
  const comps = topo.components ?? []

  // Metadata lookups: topics carry the contract, connectors the external
  // system a component's inline reference resolves against.
  const topicMeta = new Map(
    (topo.topics ?? []).map((t) => [`${t.pubsub}/${t.topic}`, t]),
  )
  const connMeta = new Map((topo.connectors ?? []).map((c) => [c.name, c]))

  // A topic node is identified by its (pubsub, topic) pair; a component by ref.
  const topicId = (pubsub: string, topic: string): string => `topic:${pubsub}/${topic}`

  // Map component refs to integration paths (a component's directory is its
  // name relative to the system root) so clicking a declared node selects the
  // scaffolded integration when one exists.
  const joinProject = (base: string, project: string): string => {
    if (project === '.' || project === '') return base
    return base === '.' ? project : `${base}/${project}`
  }
  const nodeId = new Map<string, string>()
  for (const c of comps) {
    const path = joinProject(topo.path, c.name)
    const matched = items.some((it) => it.path === path) ? path : undefined
    nodeId.set(`component:${c.name}`, matched ?? `component:${c.name}`)
  }

  // Collect the unique topics the components reference, and the internal flow
  // edges (component ⇄ topic) that decide layout depth.
  const topicRefs = new Map<string, { pubsub: string; topic: string }>()
  const flowEdges: Array<{ from: string; to: string }> = []
  for (const c of comps) {
    const cref = `component:${c.name}`
    for (const p of c.publishes ?? []) {
      const tid = topicId(p.pubsub, p.topic)
      topicRefs.set(tid, { pubsub: p.pubsub, topic: p.topic })
      flowEdges.push({ from: cref, to: tid })
    }
    for (const s of c.subscribes ?? []) {
      const tid = topicId(s.pubsub, s.topic)
      topicRefs.set(tid, { pubsub: s.pubsub, topic: s.topic })
      flowEdges.push({ from: tid, to: cref })
    }
  }
  for (const tid of topicRefs.keys()) nodeId.set(tid, tid)

  // Longest-path layering over the internal flow edges decides each node's
  // column. Kahn-style relaxation; anything left by a cycle lands in column 0
  // rather than failing the render.
  const internal = new Set<string>([
    ...comps.map((c) => `component:${c.name}`),
    ...topicRefs.keys(),
  ])
  const succ = new Map<string, string[]>()
  const indeg = new Map<string, number>()
  for (const r of internal) {
    succ.set(r, [])
    indeg.set(r, 0)
  }
  for (const e of flowEdges) {
    if (!internal.has(e.from) || !internal.has(e.to)) continue
    succ.get(e.from)?.push(e.to)
    indeg.set(e.to, (indeg.get(e.to) ?? 0) + 1)
  }
  const depth = new Map<string, number>()
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + cols * NODE_W + (cols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'
  const rowsInCol: number[] = new Array<number>(cols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    return { x: colX(d), y: contentTop + row * (NODE_H + ROW_GAP), row }
  }

  // Component positions, keyed by ref, so externals can anchor to the
  // component they touch instead of the far edge of the canvas.
  const compPos = new Map<string, { x: number; y: number; col: number }>()
  for (const c of comps) {
    const ref = `component:${c.name}`
    const col = depth.get(ref) ?? 0
    const pos = place(col)
    compPos.set(ref, { x: pos.x, y: pos.y, col })
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.kind,
        dataFlow: dataFlowFor(c.kind),
        selected: false,
      } satisfies IntNodeData,
    })
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const meta = topicMeta.get(`${ref.pubsub}/${ref.topic}`)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: meta?.contract,
      } satisfies TopicNodeData,
    })
  }

  const maxRows = Math.max(1, ...rowsInCol)
  const groupHeight = contentTop + maxRows * (NODE_H + ROW_GAP) - ROW_GAP + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system, count: comps.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Topic publish/subscribe edges. A publish leaves the component's right
  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')
  // handle for the subscriber.
  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    for (const p of c.publishes ?? []) {
      const target = nodeId.get(topicId(p.pubsub, p.topic))
      if (!target) continue
      edges.push({
        id: `e:pub:${c.name}:${p.pubsub}/${p.topic}`,
        source: comp,
        sourceHandle: 'ext',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
    for (const s of c.subscribes ?? []) {
      const source = nodeId.get(topicId(s.pubsub, s.topic))
      if (!source) continue
      edges.push({
        id: `e:sub:${s.pubsub}/${s.topic}:${c.name}`,
        source,
        sourceHandle: 'out',
        target: comp,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
  }

  // Externals sit outside the boundary, anchored to the component they touch
  // so edges stay short: an input connector directly left of its component,
  // an output connector dropped below the component's column (stacked when
  // several share one). This avoids the whole-diagram crossings that a fixed
  // left/right screen edge produces in a multi-column pipeline.
  const belowCount = new Map<number, number>()
  const belowY = (col: number): number => {
    const n = belowCount.get(col) ?? 0
    belowCount.set(col, n + 1)
    return groupHeight + EXT_VGAP + n * (EXT_H + EXT_VGAP)
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }
  const centerUnder = (x: number) => x + (NODE_W - EXT_W) / 2

  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    const anchor = compPos.get(cref)!
    for (const use of c.connectors ?? []) {
      const conn = connMeta.get(use.connector)
      const isInput = use.direction === 'in'
      const extId = `ext:${use.connector}`
      const data: ExtNodeData = {
        name: conn?.externalSystem ? refName(conn.externalSystem) : use.connector,
        type: 'connector',
        direction: isInput ? 'input' : undefined,
        connector: use.connector,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id: `e:conn:${c.name}:${use.connector}`,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, centerUnder(anchor.x), belowY(anchor.col))
        edges.push({
          id: `e:conn:${c.name}:${use.connector}`,
          source: comp,
          sourceHandle: 'infra',
          target: extId,
          targetHandle: 'top',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
    }
  }

  return { nodes, edges }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, dataFlow, selected, trigger } = data as IntNodeData
  const Icon = dataFlow ? DATA_FLOW_ICONS[dataFlow] : MemoryIcon
  return (
    <div className={`rf-int${selected ? ' selected' : ''}`}>
      <div className="rf-int-head">
        <Icon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
        {trigger && (
          <span className="rf-int-tag" title="schedule trigger">
            {trigger}
          </span>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// TopicNode is a declared pub/sub topic: the first-class hop between
// components a declared topology makes visible. Contract topics show their
// contract ref; internal ones their data entity.
function TopicNode({ data }: NodeProps) {
  const { name, entity, contract } = data as TopicNodeData
  // Topic names share a long common prefix, so lead with the short entity and
  // keep the full topic/contract in a tooltip. Fall back to the name when a
  // topic declares no entity.
  const primary = entity ?? name
  const secondary = contract ?? name
  const tip = contract ? `${name}\n${contract}` : name
  return (
    <div className="rf-infra pubsub" title={tip}>
      <Handle type="target" position={Position.Left} id="in" />
      <HubIcon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{primary}</span>
        <span className="rf-infra-kind">{secondary}</span>
      </div>
      <Handle type="source" position={Position.Right} id="out" />
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type, direction } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  const kind = direction === 'input' ? 'source' : isDisk ? 'disk' : 'external'
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="target" position={Position.Top} id="top" />
      <Handle type="source" position={Position.Right} id="out" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

const NODE_TYPES = {
  group: GroupNode,
  integration: IntegrationNode,
  external: ExternalNode,
  topic: TopicNode,
}

package kustomize

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"gopkg.in/yaml.v3"
)

// Normalize canonicalises a rendered manifest stream so two renders can be
// compared meaningfully.
//
// Documents are sorted by identity — apiVersion, kind, namespace, name — because
// kustomize's output order is not guaranteed stable across edits, and a
// reordered document would otherwise show up as a large deletion followed by a
// large insertion. Each document is re-encoded through yaml.Node rather than a
// map, which preserves the key order as authored: decoding into map[string]any
// would reorder every key on every render and bury the one line that changed.
func Normalize(manifests []byte) ([]byte, error) {
	return normalize(manifests, false)
}

// NormalizeJSON canonicalises manifests that arrive as one JSON document each,
// which is how ArgoCD's render endpoint returns them.
//
// JSON is valid YAML, so the documents parse without conversion — but yaml.v3
// records the flow style it decoded them from and would re-encode every resource
// onto a single line. The style is therefore cleared, which yields block YAML
// comparable line by line with anything Normalize produces. Key order survives:
// it is the order the JSON carried.
func NormalizeJSON(docs []string) ([]byte, error) {
	return normalize([]byte(strings.Join(docs, "\n---\n")), true)
}

// Identities names the resources in a normalised stream, in stream order.
//
// The name is built from the same apiVersion/kind/namespace/name tuple documents
// are sorted by, so it identifies a resource uniquely and two streams can be
// compared as sets — but it is written to be read, because a caller comparing two
// renders reports the difference to someone.
func Identities(normalized []byte) ([]string, error) {
	docs, err := splitDocuments(normalized, false)
	if err != nil {
		return nil, err
	}
	ids := make([]string, 0, len(docs))
	for _, doc := range docs {
		ids = append(ids, doc.name)
	}
	return ids, nil
}

func normalize(manifests []byte, block bool) ([]byte, error) {
	docs, err := splitDocuments(manifests, block)
	if err != nil {
		return nil, err
	}

	// A stable sort keeps documents that share an identity — which is invalid
	// input, but not this function's business to reject — in input order.
	stableSortBy(docs, func(a, b document) bool { return a.key < b.key })

	var out bytes.Buffer
	for i, doc := range docs {
		if i > 0 {
			out.WriteString("---\n")
		}
		out.Write(doc.text)
	}
	return out.Bytes(), nil
}

type document struct {
	// key sorts, name is the same identity written for a person to read.
	key  string
	name string
	text []byte
}

// splitDocuments parses a manifest stream into re-encoded documents. block
// forces block style, for input that was JSON.
func splitDocuments(manifests []byte, block bool) ([]document, error) {
	dec := yaml.NewDecoder(bytes.NewReader(manifests))
	var docs []document
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, fmt.Errorf("parse rendered manifests: %w", err)
		}
		// An empty document (a stray "---") decodes to a zero node.
		if node.Kind == 0 {
			continue
		}
		if block {
			clearFlowStyle(&node)
		}

		var buf bytes.Buffer
		enc := yaml.NewEncoder(&buf)
		enc.SetIndent(2)
		if err := enc.Encode(&node); err != nil {
			return nil, fmt.Errorf("re-encode rendered manifest: %w", err)
		}
		enc.Close()

		docs = append(docs, document{key: identityOf(&node), name: describeIdentity(&node), text: buf.Bytes()})
	}
	return docs, nil
}

// clearFlowStyle strips the style flags off a node and everything under it, so a
// tree decoded from JSON re-encodes as block YAML rather than as the single line
// it came in on.
func clearFlowStyle(n *yaml.Node) {
	n.Style = 0
	for _, child := range n.Content {
		clearFlowStyle(child)
	}
}

// identityOf builds the sort key from a resource's identity fields. Missing
// fields sort first, which groups malformed documents together rather than
// scattering them.
func identityOf(node *yaml.Node) string {
	root := node
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	apiVersion := mappingValue(root, "apiVersion")
	kind := mappingValue(root, "kind")
	metadata := mappingNode(root, "metadata")
	namespace := mappingValue(metadata, "namespace")
	name := mappingValue(metadata, "name")
	return strings.Join([]string{apiVersion, kind, namespace, name}, "\x00")
}

// describeIdentity writes a resource's identity the way kubectl does, which is
// how anyone reading it already expects to see it named. It is still unique:
// none of kind, namespace or name can contain a space or a slash.
func describeIdentity(node *yaml.Node) string {
	root := node
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	metadata := mappingNode(root, "metadata")
	name := mappingValue(metadata, "name")
	if namespace := mappingValue(metadata, "namespace"); namespace != "" {
		name = namespace + "/" + name
	}
	return mappingValue(root, "kind") + " " + name
}

func mappingNode(node *yaml.Node, key string) *yaml.Node {
	if node == nil || node.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == key {
			return node.Content[i+1]
		}
	}
	return nil
}

func mappingValue(node *yaml.Node, key string) string {
	if v := mappingNode(node, key); v != nil && v.Kind == yaml.ScalarNode {
		return v.Value
	}
	return ""
}

// stableSortBy is a small insertion sort: document counts here are in the tens,
// and this keeps the comparison inline and obvious.
func stableSortBy(docs []document, less func(a, b document) bool) {
	for i := 1; i < len(docs); i++ {
		for j := i; j > 0 && less(docs[j], docs[j-1]); j-- {
			docs[j], docs[j-1] = docs[j-1], docs[j]
		}
	}
}

// Palette holds the ANSI codes used by Diff.
type Palette struct {
	Add, Del, Hunk, Reset string
}

// ColorPalette and PlainPalette are the two available renderings.
var (
	ColorPalette = Palette{Add: "\x1b[32m", Del: "\x1b[31m", Hunk: "\x1b[36m", Reset: "\x1b[0m"}
	PlainPalette = Palette{}
)

const diffContext = 3

// Diff renders a unified diff of two normalised manifest streams. An empty
// result means the renders are identical.
func Diff(before, after []byte, fromLabel, toLabel string, p Palette) string {
	a := splitLines(before)
	b := splitLines(after)
	hunks := diffHunks(a, b)
	if len(hunks) == 0 {
		return ""
	}

	var out strings.Builder
	fmt.Fprintf(&out, "--- %s\n+++ %s\n", fromLabel, toLabel)
	for _, h := range hunks {
		fmt.Fprintf(&out, "%s@@ -%d,%d +%d,%d @@%s\n", p.Hunk, h.aStart+1, h.aLen, h.bStart+1, h.bLen, p.Reset)
		for _, line := range h.lines {
			switch line[0] {
			case '+':
				fmt.Fprintf(&out, "%s%s%s\n", p.Add, line, p.Reset)
			case '-':
				fmt.Fprintf(&out, "%s%s%s\n", p.Del, line, p.Reset)
			default:
				fmt.Fprintf(&out, "%s\n", line)
			}
		}
	}
	return out.String()
}

func splitLines(b []byte) []string {
	s := string(b)
	s = strings.TrimSuffix(s, "\n")
	if s == "" {
		return nil
	}
	return strings.Split(s, "\n")
}

type hunk struct {
	aStart, aLen int
	bStart, bLen int
	lines        []string
}

// diffHunks produces unified-diff hunks from a longest-common-subsequence
// table. Manifest renders for one component are hundreds of lines, so the
// quadratic table is cheap and the implementation stays readable.
func diffHunks(a, b []string) []hunk {
	lcs := lcsTable(a, b)

	// Walk the table to build the full edit script first, then group it.
	type edit struct {
		op   byte // ' ', '-', '+'
		text string
	}
	var script []edit
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		switch {
		case a[i] == b[j]:
			script = append(script, edit{' ', a[i]})
			i++
			j++
		case lcs[i+1][j] >= lcs[i][j+1]:
			script = append(script, edit{'-', a[i]})
			i++
		default:
			script = append(script, edit{'+', b[j]})
			j++
		}
	}
	for ; i < len(a); i++ {
		script = append(script, edit{'-', a[i]})
	}
	for ; j < len(b); j++ {
		script = append(script, edit{'+', b[j]})
	}

	// Collect the positions of the changed edits.
	var changedAt []int
	for k, e := range script {
		if e.op != ' ' {
			changedAt = append(changedAt, k)
		}
	}
	if len(changedAt) == 0 {
		return nil
	}

	// Record each edit's line number on both sides, for the hunk headers.
	lineNums := make([][2]int, len(script))
	aLine, bLine := 0, 0
	for k, e := range script {
		lineNums[k] = [2]int{aLine, bLine}
		switch e.op {
		case ' ':
			aLine++
			bLine++
		case '-':
			aLine++
		case '+':
			bLine++
		}
	}

	// Group changes whose gap is small enough that their context windows would
	// overlap, so nearby edits share one hunk instead of repeating context.
	type group struct{ first, last int }
	groups := []group{{changedAt[0], changedAt[0]}}
	for _, k := range changedAt[1:] {
		if last := &groups[len(groups)-1]; k-last.last > 2*diffContext {
			groups = append(groups, group{k, k})
		} else {
			last.last = k
		}
	}

	hunks := make([]hunk, 0, len(groups))
	for _, g := range groups {
		start := max(0, g.first-diffContext)
		stop := min(len(script), g.last+diffContext+1)

		h := hunk{aStart: lineNums[start][0], bStart: lineNums[start][1]}
		for _, e := range script[start:stop] {
			h.lines = append(h.lines, string(e.op)+e.text)
			switch e.op {
			case ' ':
				h.aLen++
				h.bLen++
			case '-':
				h.aLen++
			case '+':
				h.bLen++
			}
		}
		hunks = append(hunks, h)
	}
	return hunks
}

func lcsTable(a, b []string) [][]int {
	table := make([][]int, len(a)+1)
	for i := range table {
		table[i] = make([]int, len(b)+1)
	}
	for i := len(a) - 1; i >= 0; i-- {
		for j := len(b) - 1; j >= 0; j-- {
			if a[i] == b[j] {
				table[i][j] = table[i+1][j+1] + 1
			} else {
				table[i][j] = max(table[i+1][j], table[i][j+1])
			}
		}
	}
	return table
}

package dashboard

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"path/filepath"
	"reflect"
	"sync"
	"testing"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

// deployWorkspace writes the layout `sys create` produces inside a domain
// folder, so the served summary carries a domain and a system as well as a name
// — the three things the deploy status command needs to find a component
// unambiguously.
//
// It returns the root-relative path of the one integration in it.
func deployWorkspace(t *testing.T) string {
	t.Helper()
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "sales", "ordersync", "order-extract"), "extractor", "v0.2.0")
	writeSystemHost(t, filepath.Join(tmp, "sales", "ordersync", "system-host"), "ordersync")
	return "sales/ordersync/order-extract"
}

// stubStatus is a StatusResult shaped like the state the release process is
// meant to end in, with the prose the command would have printed beneath it.
func stubStatus() *deploy.StatusResult {
	return &deploy.StatusResult{
		Component: "order-extract",
		Domain:    "sales",
		System:    "ordersync",
		Kind:      "service",
		Environments: []deploy.EnvironmentStatus{{
			Environment: "dev",
			AppName:     "sales-ordersync-order-extract-dev",
			Onboarded:   true,
			Release:     "1.4.2",
			Pins:        []deploy.ResultPin{{Image: "reg/order-extract", Digest: "sha256:ad22d6f2ecbc"}},
			SyncPolicy:  "auto",
			SyncStatus:  "Synced",
		}},
		Consistent: true,
		Summary:    "only dev is onboarded, so there is nothing to compare it with",
		Notes:      []string{"dev pins nothing for reg/other, so it has never been deployed there"},
	}
}

func deployJSON(t *testing.T, h http.Handler, method, path string) map[string]any {
	t.Helper()
	var rec = get(t, h, path)
	if method == http.MethodPost {
		rec = post(t, h, path)
	}
	if rec.Code != http.StatusOK {
		t.Fatalf("%s %s status = %d, want 200: %s", method, path, rec.Code, rec.Body.String())
	}
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	return body
}

// The endpoint's whole job is to hand the command's own result through without
// editing it — including the prose, which is what keeps the panel and the
// terminal from drawing different conclusions from the same overlays.
func TestDeployStateCarriesTheCommandResultThrough(t *testing.T) {
	path := deployWorkspace(t)
	h := testHandlerWithDeploy(t, ".", func(context.Context, integrationSummary) deployState {
		return deployState{Status: stubStatus(), ReadAt: time.Now()}
	})

	body := deployJSON(t, h, http.MethodGet, "/api/deploy/"+path)
	status, ok := body["status"].(map[string]any)
	if !ok {
		t.Fatalf("status missing from payload: %v", body)
	}
	if status["summary"] != "only dev is onboarded, so there is nothing to compare it with" {
		t.Errorf("summary = %v, want the command's sentence", status["summary"])
	}
	notes, ok := status["notes"].([]any)
	if !ok || len(notes) != 1 {
		t.Fatalf("notes = %v, want the command's one note", status["notes"])
	}
	if status["consistent"] != true {
		t.Errorf("consistent = %v, want true", status["consistent"])
	}
	if body["readAt"] == nil {
		t.Error("readAt should be served so a reader can tell how current this is")
	}
	if _, present := body["error"]; present {
		t.Errorf("a successful read should carry no error: %v", body["error"])
	}
}

// An unconfigured repository, an ambiguous name and a held checkout lock are all
// statements about the lookup rather than about the integration, and the command
// already words each of them well. Rewriting one here would be a second thing to
// keep true, and would risk turning "we could not find out" into "not deployed".
// The single exception is the not-found case itself, which describeError owns.
func TestDeployStateServesTheCommandErrorVerbatim(t *testing.T) {
	path := deployWorkspace(t)
	const msg = "no GitOps repository configured; pass --gitops-repo, set INTROPY_GITOPS_REPO, or add gitopsRepo to /home/x/.config/intropy/config.yaml"
	h := testHandlerWithDeploy(t, ".", func(context.Context, integrationSummary) deployState {
		return deployState{Error: msg, ReadAt: time.Now()}
	})

	body := deployJSON(t, h, http.MethodGet, "/api/deploy/"+path)
	if body["error"] != msg {
		t.Errorf("error = %q, want the command's message unchanged:\n%q", body["error"], msg)
	}
	if _, present := body["status"]; present {
		t.Error("an error must not come with a status: an empty ladder reads as 'not deployed'")
	}
}

// The command names the repository it refreshed and any environment ArgoCD could
// not be read for. Both are provenance for what the ladder shows, so they are
// served rather than dropped on the floor.
func TestDeployStateServesTheCommandDiagnostics(t *testing.T) {
	path := deployWorkspace(t)
	h := testHandlerWithDeploy(t, ".", func(context.Context, integrationSummary) deployState {
		return deployState{
			Status:      stubStatus(),
			Diagnostics: diagnosticLines("refreshing git@example.com:acme/gitops.git\nwarning: not reading sync or health from ArgoCD: no token\n"),
			ReadAt:      time.Now(),
		}
	})

	body := deployJSON(t, h, http.MethodGet, "/api/deploy/"+path)
	got, ok := body["diagnostics"].([]any)
	if !ok || len(got) != 2 {
		t.Fatalf("diagnostics = %v, want the two stderr lines", body["diagnostics"])
	}
	if got[0] != "refreshing git@example.com:acme/gitops.git" {
		t.Errorf("first diagnostic = %v, want the repository it refreshed", got[0])
	}
}

// The not-found translation is the one exception to verbatim pass-through:
// both of the command's not-found variants read as "not deployed yet" here,
// because the dashboard's domain and system come from the workspace folders,
// so the command's corrective detail is noise next to an empty ladder.
func TestDescribeError(t *testing.T) {
	sum := integrationSummary{Name: "order-extractor"}

	notFound := fmt.Errorf("%w: no component.yaml for %q under domains/\nthe repository defines: order-extractor",
		gitops.ErrComponentNotFound, "order-loader")
	if got := describeError(sum, notFound); got != "order-extractor is not deployed yet" {
		t.Errorf("describeError(not found) = %q, want the not-deployed phrasing", got)
	}

	wrongPlace := fmt.Errorf("%w: %q exists at orders/order-flow/order-extractor, not under the domain/system given",
		gitops.ErrComponentNotFound, "order-extractor")
	if got := describeError(sum, wrongPlace); got != "order-extractor is not deployed yet" {
		t.Errorf("describeError(wrong domain) = %q, want the not-deployed phrasing", got)
	}

	other := errors.New("no GitOps repository configured")
	if got := describeError(sum, other); got != other.Error() {
		t.Errorf("describeError(other) = %q, want the command's message unchanged", got)
	}
}

func TestDiagnosticLines(t *testing.T) {
	for _, tc := range []struct {
		name   string
		stderr string
		want   []string
	}{
		{"empty is nil so the field is omitted", "", nil},
		{"blank lines only", "\n  \n\n", nil},
		{"trailing newline does not make an entry", "refreshing x\n", []string{"refreshing x"}},
