	tmp := t.TempDir()
	t.Chdir(tmp)
	writeScaffold(t, filepath.Join(tmp, "sales", "ordersync", "order-extract"), "extractor", "v0.2.0")
	writeScaffold(t, filepath.Join(tmp, "sales", "ordersync", "order-load"), "loader", "v0.2.0")
