	inFlight, overlapped := 0, false
	h := testHandlerWithDeploy(t, ".", func(context.Context, integrationSummary) deployState {
		mu.Lock()
		inFlight++
		if inFlight > 1 {
			overlapped = true
		}
		mu.Unlock()

		time.Sleep(20 * time.Millisecond)

		mu.Lock()
		inFlight--
		mu.Unlock()
		return deployState{Status: stubStatus()}
