package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/deploy"
)

// gitopsProvider reports what the GitOps repository declares, as one document.
//
// Like deployProvider it never fails: a repository that cannot be described
// comes back with Error set rather than an error return, because "we could
// not find out" and "nothing is declared" must not render the same. Which of
// the two it was is the command's business to say, not this package's to guess.
type gitopsProvider func(ctx context.Context) gitopsState

// gitopsState is the repository-level declaration, or the reason it has none.
type gitopsState struct {
	// Show is deploy show's own result, passed through unchanged so that the
	// dashboard and the command line cannot come to different conclusions
	// about the same checkout.
	Show *deploy.ShowResult `json:"show,omitempty"`

	// Error is the command's own message, verbatim — an unconfigured GitOps
	// repository, a checkout another deploy is holding, a missing deploy.yaml.
	// Served rather than restated: those messages already name every way to
	// resolve them, and a paraphrase here would be a second thing to keep true.
	Error string `json:"error,omitempty"`

	// Diagnostics is what the command wrote to stderr, one entry per line:
	// which repository it refreshed, and any manifest document the secret
	// scanner skipped. Provenance for what Show reports, not a failure.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// ReadAt is when the command ran, so a reader can tell how current this is.
	ReadAt time.Time `json:"readAt"`
}

// showCommandProvider is the default provider: it runs the deploy show
// command with a JSON writer and decodes what it prints.
//
// Calling the command rather than reading the GitOps tree here is deliberate.
// Show already owns every refusal that matters — an unset gitopsRepo, a
// checkout lock held elsewhere, a missing or invalid deploy.yaml — and each of
// those is a case where the honest answer is subtle and already written down.
// A second implementation would have to get all of them right again.
func showCommandProvider(version string) gitopsProvider {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context) gitopsState {
		var out, logs bytes.Buffer
		err := deploy.Show(ctx, deploy.ShowOptions{
			OutputFormat: deploy.OutputJSON,
			UserAgent:    userAgent,
			Stdout:       &out,
			Stderr:       &logs,
		})

		state := gitopsState{Diagnostics: diagnosticLines(logs.String()), ReadAt: time.Now()}
		if err != nil {
			state.Error = err.Error()
			return state
		}

		var res deploy.ShowResult
		if err := json.Unmarshal(out.Bytes(), &res); err != nil {
			// The command succeeded but printed something this cannot read —
			// a version skew rather than anything about the repository.
			state.Error = fmt.Sprintf("read deploy show output: %v", err)
			return state
		}
		state.Show = &res
		return state
	}
}

