// writeTree places content at a repository-relative path.
func writeTree(t *testing.T, root, rel, content string) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

var showCoord = gitops.Coordinate{Domain: "orders", System: "order-flow", Component: "order-flow-shared"}

func scan(t *testing.T, root string, coord gitops.Coordinate) (refs []SecretRef, diagnostics string) {
	t.Helper()
	var stderr bytes.Buffer
	return scanComponentSecrets(root, coord, &stderr), stderr.String()
}

// The scanner's job in one fixture: the three secret-bearing kinds plus a
// secretGenerator, none of them rendered, each named with where it was seen.
func TestScanFindsEverySecretKind(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/base/secret.yaml", `apiVersion: v1
kind: Secret
metadata:
  name: rabbitmq-credentials
stringData:
  password: not-read
`)
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/base/external-secret.yaml", `apiVersion: external-secrets.io/v1beta1
kind: ExternalSecret
metadata:
  name: kv-sync
spec:
  secretStoreRef:
    name: vault
`)
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/overlays/prod/sealed.yaml", `apiVersion: bitnami.com/v1alpha1
kind: SealedSecret
metadata:
  name: db-password
`)
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/overlays/prod/kustomization.yaml", `apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
resources:
  - ../../base
  - sealed.yaml
secretGenerator:
  - name: app-secret
    literals:
      - TOKEN=placeholder
`)
	// A deployment beside the secrets must not be reported: the scanner names
	// secret-bearing resources, not every document it passes.
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/base/component.yaml", `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: rabbitmq
`)

	refs, _ := scan(t, root, showCoord)

	want := []SecretRef{
		{Kind: "ExternalSecret", Name: "kv-sync", Component: "orders/order-flow/order-flow-shared", File: "domains/orders/order-flow/order-flow-shared/base/external-secret.yaml"},
		{Kind: "Secret", Name: "rabbitmq-credentials", Component: "orders/order-flow/order-flow-shared", File: "domains/orders/order-flow/order-flow-shared/base/secret.yaml"},
		{Kind: "secretGenerator", Name: "app-secret", Component: "orders/order-flow/order-flow-shared"},
		{Kind: "SealedSecret", Name: "db-password", Component: "orders/order-flow/order-flow-shared", File: "domains/orders/order-flow/order-flow-shared/overlays/prod/sealed.yaml"},
	}
	if !reflect.DeepEqual(refs, want) {
		t.Errorf("scanComponentSecrets() =\n%#v\nwant\n%#v", refs, want)
	}
}

// An overlay nobody declared is exactly the half-onboarded state this command
// exists to surface, so every directory under overlays/ is scanned, not just
// the ones component.yaml admits to.
func TestScanWalksUndeclaredOverlays(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/overlays/nobody/secret.yaml", `kind: Secret
metadata:
  name: orphan
`)

	refs, _ := scan(t, root, showCoord)
	if len(refs) != 1 || refs[0].Name != "orphan" {
		t.Errorf("scanComponentSecrets() = %v, want the undeclared overlay's Secret", refs)
	}
	if !strings.Contains(refs[0].File, "overlays/nobody/") {
		t.Errorf("File = %q, want it to name the undeclared overlay", refs[0].File)
	}
}

// A malformed document is a diagnostic naming the file, not a failure: this
// is a scanner, not a validator, and one broken file must not hide the rest.
func TestScanSkipsMalformedDocumentsWithADiagnostic(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, "domains/orders/order-flow/order-flow-shared/base/mixed.yaml", `kind: Secret
metadata:
  name: good
---
kind: Secret
  metadata: [this is not a mapping
`)

	refs, stderr := scan(t, root, showCoord)
	if len(refs) != 1 || refs[0].Name != "good" {
		t.Errorf("scanComponentSecrets() = %v, want the readable document", refs)
	}
	if !strings.Contains(stderr, "mixed.yaml") {
		t.Errorf("stderr should name the file with the malformed document:\n%s", stderr)
	}
}

// A repository with no secret resources still gets an explicit answer:
// "none declared", lowercase, not an absent section.
func TestShowRendersAnExplicitEmptySecretsState(t *testing.T) {
	var stdout bytes.Buffer
	res := ShowResult{
		Repository: RepositoryInfo{URL: "git@example.com:acme/gitops.git"},
		Registry:   "harbor.intropy.io",
		Argocd:     ArgocdInfo{Server: "argocd.intropy.io"},
		Environments: []EnvironmentInfo{
			{Name: "dev", Sync: "auto"},
		},
	}
	if err := reportShow(output{Format: OutputPlain, Stdout: &stdout}, res); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(stdout, "none declared") {
		t.Errorf("empty secrets should render explicitly:\n%s", stdout.String())
	}
}

// The plain report renders the environments in the order the result carries
// them — promotion order — with sync policy and promotion edges alongside.
func TestShowRendersEnvironmentsInPromotionOrder(t *testing.T) {
	var stdout bytes.Buffer
	res := ShowResult{
		Repository: RepositoryInfo{URL: "git@example.com:acme/gitops.git", Revision: "a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2"},
		Registry:   "harbor.intropy.io",
		Argocd:     ArgocdInfo{Server: "argocd.intropy.io", AppNamespace: "customer-fluxia"},
		Platform:   PlatformInfo{Provider: "azure", SecretStore: "azure.keyvault"},
		Environments: []EnvironmentInfo{
			{Name: "dev", Sync: "auto"},
			{Name: "staging", Sync: "auto", PromotesFrom: []string{"dev"}},
			{Name: "prod", Sync: "manual", PromotesFrom: []string{"staging"}, RequireSourceHealthy: true},
		},
	}
	if err := reportShow(output{Format: OutputPlain, Stdout: &stdout}, res); err != nil {
		t.Fatal(err)
	}
	out := stdout.String()

	dev, staging, prod := strings.Index(out, "dev"), strings.Index(out, "staging"), strings.Index(out, "prod")
	if !(dev < staging && staging < prod) {
		t.Errorf("environments should read dev, staging, prod; got positions %d, %d, %d:\n%s", dev, staging, prod, out)
	}
	for _, want := range []string{"harbor.intropy.io", "argocd.intropy.io", "customer-fluxia", "azure.keyvault", "source healthy"} {
		if !strings.Contains(out, want) {
			t.Errorf("output should name %q:\n%s", want, out)
		}
	}
	// The header shows the revision short; the full value is the JSON contract's.
	if !strings.Contains(out, "@ a1b2c3d") {
		t.Errorf("repository should show the short revision:\n%s", out)
	}
	if strings.Contains(out, "a1b2c3d4e5f6") {
		t.Errorf("plain output should not carry the full sha:\n%s", out)
	}
}

// A component whose component.yaml did not load is a row with an error, not a
// gap: the tree still knows its name, and the reader should see that much.
func TestShowRendersAComponentErrorInline(t *testing.T) {
	var stdout bytes.Buffer
	res := ShowResult{
		Repository: RepositoryInfo{URL: "git@example.com:acme/gitops.git"},
		Registry:   "harbor.intropy.io",
		Argocd:     ArgocdInfo{Server: "argocd.intropy.io"},
		Systems: []SystemInfo{{
			Domain: "orders", System: "order-flow",
			Components: []ComponentInfo{
				{Name: "order-extractor", Kind: "service", Environments: []string{"dev"}},
				{Name: "broken", Error: "parse component.yaml: name is required"},
			},
		}},
	}
	if err := reportShow(output{Format: OutputPlain, Stdout: &stdout}, res); err != nil {
		t.Fatal(err)
	}
	out := stdout.String()
	if !strings.Contains(out, "broken") || !strings.Contains(out, "name is required") {
		t.Errorf("the broken component should render with its error:\n%s", out)
	}
	if !strings.Contains(out, "order-extractor") {
		t.Errorf("the healthy component should still be listed:\n%s", out)
	}
}

// The JSON contract is the machine-readable form of the same result; pinning
// the field names guards a consumer (the dashboard) that decodes them.
func TestShowResultJSONRoundTrip(t *testing.T) {
	res := ShowResult{
		Repository: RepositoryInfo{URL: "git@example.com:acme/gitops.git", Revision: "abc123"},
		Registry:   "harbor.intropy.io",
		Argocd:     ArgocdInfo{Server: "argocd.intropy.io", AppNamespace: "customer-fluxia"},
		Platform:   PlatformInfo{SecretStore: "vault"},
		Environments: []EnvironmentInfo{
			{Name: "dev", Sync: "auto", Scratch: true},
			{Name: "prod", Sync: "manual", PromotesFrom: []string{"dev"}, RequireSourceHealthy: true},
		},
		Systems: []SystemInfo{{
			Domain: "orders", System: "order-flow",
			Components: []ComponentInfo{{
				Name:         "order-flow-shared",
				Kind:         "shared",
				Environments: []string{"dev", "prod"},
				Secrets: []SecretRef{
					{Kind: "Secret", Name: "creds", Component: "orders/order-flow/order-flow-shared", File: "domains/orders/order-flow/order-flow-shared/base/secret.yaml"},
					{Kind: "secretGenerator", Name: "gen", Component: "orders/order-flow/order-flow-shared"},
				},
			}},
		}},
	}

	var buf bytes.Buffer
	if err := reportShow(output{Format: OutputJSON, Stdout: &buf}, res); err != nil {
		t.Fatal(err)
	}
	var got ShowResult
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("stdout is not valid JSON: %v\n%s", err, buf.String())
	}
	if !reflect.DeepEqual(got, res) {
		t.Errorf("round trip =\n%#v\nwant\n%#v", got, res)
	}

	// Absent, not empty: an undeclared platform value must be tellable apart
	// from an empty one, and a secretGenerator carries no file.
	var raw map[string]any
	if err := json.Unmarshal(buf.Bytes(), &raw); err != nil {
		t.Fatal(err)
	}
	platform := raw["platform"].(map[string]any)
	if _, present := platform["provider"]; present {
		t.Errorf("an undeclared provider should be omitted, not served empty: %v", platform)
	}
	secrets := raw["systems"].([]any)[0].(map[string]any)["components"].([]any)[0].(map[string]any)["secrets"].([]any)
	if _, present := secrets[1].(map[string]any)["file"]; present {
		t.Errorf("a secretGenerator should carry no file: %v", secrets[1])
	}
}

