// ResourceRef names one manifest resource and where it was seen.
type ResourceRef struct {
	APIVersion string `json:"apiVersion"`
	Kind       string `json:"kind"`
	Name       string `json:"name"`

	// File is the repository-relative file the resource is declared in. The
	// same resource appearing in base/ and an overlay is one entry per
	// location: this reports files, not rendered state.
	File string `json:"file"`
}

// SecretReference is a secret a manifest consumes by name, without the
// repository necessarily declaring it.
type SecretReference struct {
	// Name is the secret's name from the secretKeyRef.
	Name string `json:"name"`

	// Resource is the referring resource, as "kind name" — the same form
	// kustomize.Identities renders.
	Resource string `json:"resource"`

	// File is the repository-relative file the reference appears in.
	File string `json:"file"`
}

