// References print under the owned secrets, separately: merged into one
// list they would read as declarations.
func TestShowRendersSecretReferencesSeparately(t *testing.T) {
	var stdout bytes.Buffer
	res := ShowResult{
		Repository: RepositoryInfo{URL: "git@example.com:acme/gitops.git"},
		Registry:   "harbor.intropy.io",
		Argocd:     ArgocdInfo{Server: "argocd.intropy.io"},
		Systems: []SystemInfo{{
			Domain: "orders", System: "order-flow",
			Components: []ComponentInfo{{
				Name:         "order-extractor",
				Kind:         "service",
				Environments: []string{"dev"},
				Secrets: []SecretRef{
					{Kind: "Secret", Name: "creds", Component: "orders/order-flow/order-extractor", File: "domains/orders/order-flow/order-extractor/base/secret.yaml"},
				},
				SecretRefs: []SecretReference{
					{Name: "order-extractor-s3", Resource: "Component binding.order-source", File: "domains/orders/order-flow/order-extractor/base/binding.yaml"},
				},
			}},
		}},
	}
	if err := reportShow(output{Format: OutputPlain, Stdout: &stdout}, res); err != nil {
		t.Fatal(err)
	}
	out := stdout.String()
	if !strings.Contains(out, "references") {
		t.Errorf("references should be their own list:\n%s", out)
	}
	if !strings.Contains(out, "order-extractor-s3") || !strings.Contains(out, "Component binding.order-source") {
		t.Errorf("the reference should name the secret and what refers to it:\n%s", out)
	}
	// Owned before referenced: "creds" above the references heading.
	if strings.Index(out, "creds") > strings.Index(out, "references") {
		t.Errorf("owned secrets should render before the references:\n%s", out)
	}
}

// The plain report renders the environments in the order the result carries
// them — promotion order — with sync policy and promotion edges alongside.

// The inventory is every resource a component declares, secret-bearing or
// not: "what is this component made of" without any rendering.
func TestShowInventoriesComponentResources(t *testing.T) {
	_, cacheRoot := newShowFixture(t)
	res, _ := showJSON(t, cacheRoot)

	extractor := componentByName(t, res, "order-extractor")
	byKind := map[string]string{}
	for _, r := range extractor.Resources {
		byKind[r.Kind] = r.File
	}
	for _, kind := range []string{"Deployment", "Component"} {
		if byKind[kind] == "" {
			t.Errorf("order-extractor should declare a %s, resources: %v", kind, byKind)
		}
	}
	if !strings.HasPrefix(byKind["Component"], "domains/orders/order-flow/order-extractor/") {
		t.Errorf("the Component's file should be repo-relative, got %q", byKind["Component"])
	}

	// The binding consumes order-extractor-s3, which nothing in the tree
	// declares: a reference, not an owned secret.
	if len(extractor.SecretRefs) != 1 || extractor.SecretRefs[0].Name != "order-extractor-s3" {
		t.Errorf("secretRefs = %v, want the binding's reference", extractor.SecretRefs)
	}
	if extractor.SecretRefs[0].Resource != "Component binding.order-source" {
		t.Errorf("the reference should name what refers to it: %+v", extractor.SecretRefs[0])
	}
	for _, s := range extractor.Secrets {
		if s.Name == "order-extractor-s3" {
			t.Errorf("a reference must not be reported as an owned secret: %+v", s)
		}
	}
}

// A read-only command must leave the repository exactly as it found it.
func TestShowWritesNothing(t *testing.T) {

/** One manifest resource and where it was seen. One entry per document per
 *  location: the manifests are never rendered, so this says where a resource
 *  is declared, not what a kustomize build would make of it. */
export interface ResourceRef {
  apiVersion: string
  kind: string
  name: string
  /** Repository-relative file. */
  file: string
}

/** A secret a manifest consumes by name without the repository necessarily
 *  declaring it — a binding's credentials, a provisioned-elsewhere
 *  connection string. A referenced secret that exists nowhere is exactly the
 *  gap an operator needs to see. */
export interface SecretReference {
  name: string
  /** The referring resource, as "kind name". */
  resource: string
  file: string
}

export interface ComponentInfo {
  name: string
  kind: 'service' | 'shared' | string
  images?: string[]
  /** The component.yaml declared list, verbatim — NOT promotion order. */
  environments: string[]
  /** Every manifest resource the component declares. */
  resources?: ResourceRef[]
  secrets?: SecretRef[]
  /** Secrets the component references without owning. */
  secretRefs?: SecretReference[]
  /** An unreadable or invalid component.yaml; the rest of the tree still lists. */
  error?: string
}

